fn pip_command_help(usage: &str, lines: &[&str]) -> String {
    let mut output = format!("OMC pip compatibility\n\nUsage: {usage}\n");
    if !lines.is_empty() {
        output.push('\n');
        for line in lines {
            output.push_str(line);
            output.push('\n');
        }
    }
    output
}

