fn parse_npm_dist_tag_args(args: &[String]) -> Result<NpmCompatAction, OmcRegistryError> {
    let mut positionals = Vec::new();
    let mut npm_registry = None;
    let mut userconfig = None;
    let mut otp = None;
    let mut tag_option = None;
    let mut index = 0;
    while index < args.len() {
        let arg = &args[index];
        if matches!(
            arg.as_str(),
            "--json"
                | "--silent"
                | "-s"
                | "--parseable"
                | "-p"
                | "--workspaces"
                | "--include-workspace-root"
        ) || npm_workspace_scope_ignored_flag(arg)
            || npm_dist_tag_ignored_equals_flag(arg)
        {
        } else if arg == "--registry" {
            index += 1;
            npm_registry = Some(npm_dist_tag_flag_value(args, index, arg)?);
        } else if let Some(value) = arg.strip_prefix("--registry=") {
            npm_registry = Some(value.to_owned());
        } else if arg == "--userconfig" {
            index += 1;
            userconfig = Some(PathBuf::from(npm_dist_tag_flag_value(args, index, arg)?));
        } else if let Some(value) = arg.strip_prefix("--userconfig=") {
            userconfig = Some(PathBuf::from(value));
        } else if arg == "--otp" {
            index += 1;
            otp = Some(npm_dist_tag_flag_value(args, index, arg)?);
        } else if let Some(value) = arg.strip_prefix("--otp=") {
            otp = Some(value.to_owned());
        } else if arg == "--tag" {
            index += 1;
            tag_option = Some(npm_dist_tag_flag_value(args, index, arg)?);
        } else if let Some(value) = arg.strip_prefix("--tag=") {
            tag_option = Some(value.to_owned());
        } else if matches!(arg.as_str(), "--loglevel" | "--workspace" | "-w") {
            index += 1;
            if args.get(index).is_none() {
                return Err(OmcRegistryError::UnsupportedSpec(format!(
                    "{arg} needs a value"
                )));
            }
        } else {
            positionals.push(arg.clone());
        }
        index += 1;
    }

    match positionals.first().map(String::as_str) {
        Some("add") => {
            positionals.remove(0);
            let Some(spec) = positionals.first().cloned() else {
                return Err(OmcRegistryError::UnsupportedSpec(
                    "npm dist-tag add needs a package spec with version".to_owned(),
                ));
            };
            let tag = positionals
                .get(1)
                .cloned()
                .or(tag_option)
                .unwrap_or_else(|| "latest".to_owned());
            if positionals.len() > 2 {
                return Err(unsupported_compat_arg("npm dist-tag add", &positionals[2]));
            }
            Ok(NpmCompatAction::DistTag {
                action: NpmDistTagAction::Add {
                    spec,
                    tag,
                    npm_registry,
                    userconfig,
                    otp,
                },
            })
        }
        Some("rm" | "remove" | "delete" | "del") => {
            positionals.remove(0);
            let Some(spec) = positionals.first().cloned() else {
                return Err(OmcRegistryError::UnsupportedSpec(
                    "npm dist-tag rm needs a package spec".to_owned(),
                ));
            };
            let Some(tag) = positionals.get(1).cloned().or(tag_option) else {
                return Err(OmcRegistryError::UnsupportedSpec(
                    "npm dist-tag rm needs a tag".to_owned(),
                ));
            };
            if positionals.len() > 2 {
                return Err(unsupported_compat_arg("npm dist-tag rm", &positionals[2]));
            }
            Ok(NpmCompatAction::DistTag {
                action: NpmDistTagAction::Remove {
                    spec,
                    tag,
                    npm_registry,
                    userconfig,
                    otp,
                },
            })
        }
        Some("ls" | "list") => {
            positionals.remove(0);
            if positionals.len() > 1 {
                return Err(unsupported_compat_arg("npm dist-tag ls", &positionals[1]));
            }
            Ok(NpmCompatAction::DistTag {
                action: NpmDistTagAction::List {
                    spec: positionals.pop(),
                    npm_registry,
                    userconfig,
                },
            })
        }
        _ => {
            if positionals.len() > 1 {
                return Err(unsupported_compat_arg("npm dist-tag ls", &positionals[1]));
            }
            Ok(NpmCompatAction::DistTag {
                action: NpmDistTagAction::List {
                    spec: positionals.pop(),
                    npm_registry,
                    userconfig,
                },
            })
        }
    }
}

fn npm_dist_tag_ignored_equals_flag(arg: &str) -> bool {
    [
        "--json=",
        "--loglevel=",
        "--parseable=",
        "--workspace=",
        "-w=",
        "--workspaces=",
        "--include-workspace-root=",
    ]
    .iter()
    .any(|prefix| arg.starts_with(prefix))
}

fn npm_dist_tag_flag_value(
    args: &[String],
    index: usize,
    flag: &str,
) -> Result<String, OmcRegistryError> {
    args.get(index)
        .cloned()
        .ok_or_else(|| OmcRegistryError::UnsupportedSpec(format!("{flag} needs a value")))
}

fn parse_npm_sbom_args(args: &[String]) -> Result<NpmCompatAction, OmcRegistryError> {
    let mut format = None;
    let mut sbom_type = NpmSbomType::Library;
    let mut positionals = Vec::new();
    let mut index = 0;
    while index < args.len() {
        let arg = &args[index];
        if arg == "--sbom-format" {
            index += 1;
            let value = args.get(index).ok_or_else(|| {
                OmcRegistryError::UnsupportedSpec("--sbom-format needs a value".to_owned())
            })?;
            format = Some(parse_npm_sbom_format(value)?);
        } else if let Some(value) = arg.strip_prefix("--sbom-format=") {
            format = Some(parse_npm_sbom_format(value)?);
        } else if arg == "--sbom-type" {
            index += 1;
            let value = args.get(index).ok_or_else(|| {
                OmcRegistryError::UnsupportedSpec("--sbom-type needs a value".to_owned())
            })?;
            sbom_type = parse_npm_sbom_type(value)?;
        } else if let Some(value) = arg.strip_prefix("--sbom-type=") {
            sbom_type = parse_npm_sbom_type(value)?;
        } else if matches!(
            arg.as_str(),
            "--json"
                | "--package-lock-only"
                | "--silent"
                | "-s"
                | "--workspaces"
                | "--include-workspace-root"
        ) || npm_workspace_scope_ignored_flag(arg)
            || npm_sbom_ignored_equals_flag(arg)
        {
        } else if matches!(
            arg.as_str(),
            "--omit" | "--include" | "--workspace" | "-w" | "--loglevel"
        ) {
            index += 1;
            if args.get(index).is_none() {
                return Err(OmcRegistryError::UnsupportedSpec(format!(
                    "{arg} needs a value"
                )));
            }
        } else if arg.starts_with('-') {
            return Err(unsupported_compat_arg("npm sbom", arg));
        } else {
            positionals.push(arg.clone());
        }
        index += 1;
    }

    if !positionals.is_empty() {
        return Err(unsupported_compat_arg("npm sbom", &positionals[0]));
    }
    let Some(format) = format else {
        return Err(OmcRegistryError::UnsupportedSpec(
            "npm sbom needs --sbom-format with one of: cyclonedx, spdx".to_owned(),
        ));
    };
    Ok(NpmCompatAction::Sbom {
        action: NpmSbomAction { format, sbom_type },
    })
}

fn parse_npm_sbom_format(value: &str) -> Result<NpmSbomFormat, OmcRegistryError> {
    match value {
        "cyclonedx" => Ok(NpmSbomFormat::CycloneDx),
        "spdx" => Ok(NpmSbomFormat::Spdx),
        other => Err(OmcRegistryError::UnsupportedSpec(format!(
            "unsupported npm sbom format `{other}`"
        ))),
    }
}

fn parse_npm_sbom_type(value: &str) -> Result<NpmSbomType, OmcRegistryError> {
    match value {
        "library" => Ok(NpmSbomType::Library),
        "application" => Ok(NpmSbomType::Application),
        "framework" => Ok(NpmSbomType::Framework),
        other => Err(OmcRegistryError::UnsupportedSpec(format!(
            "unsupported npm sbom type `{other}`"
        ))),
    }
}

fn npm_sbom_ignored_equals_flag(arg: &str) -> bool {
    [
        "--json=",
        "--package-lock-only=",
        "--omit=",
        "--include=",
        "--workspace=",
        "-w=",
        "--workspaces=",
        "--include-workspace-root=",
        "--loglevel=",
    ]
    .iter()
    .any(|prefix| arg.starts_with(prefix))
}

fn parse_npm_registry_identity_args(
    command: &str,
    args: &[String],
) -> Result<(bool, Option<String>, Option<PathBuf>), OmcRegistryError> {
    let mut json = false;
    let mut userconfig = None;
    let mut filtered = Vec::new();
    let mut index = 0;
    while index < args.len() {
        let arg = &args[index];
        if arg == "--json" {
            json = true;
        } else if matches!(arg.as_str(), "--silent" | "-s" | "--parseable") {
        } else if arg == "--userconfig" {
            index += 1;
            let value = args
                .get(index)
                .ok_or_else(|| OmcRegistryError::UnsupportedSpec(format!("{arg} needs a value")))?;
            userconfig = Some(PathBuf::from(value));
        } else if let Some(value) = arg.strip_prefix("--userconfig=") {
            userconfig = Some(PathBuf::from(value));
        } else if arg == "--loglevel" {
            index += 1;
            if args.get(index).is_none() {
                return Err(OmcRegistryError::UnsupportedSpec(format!(
                    "{arg} needs a value"
                )));
            }
        } else if npm_registry_identity_equals_value_flag(arg) {
        } else {
            filtered.push(arg.clone());
        }
        index += 1;
    }

    let CommonCompatFlags {
        npm_registry,
        positionals,
        ..
    } = parse_common_compat_flags(&filtered, true)?;
    if !positionals.is_empty() {
        return Err(unsupported_compat_arg(command, &positionals[0]));
    }
    Ok((json, npm_registry, userconfig))
}

fn npm_registry_identity_equals_value_flag(arg: &str) -> bool {
    ["--loglevel="].iter().any(|prefix| arg.starts_with(prefix))
}

fn parse_npm_explain_args(args: &[String]) -> Result<NpmCompatAction, OmcRegistryError> {
    let mut json = false;
    let mut specs = Vec::new();
    let mut index = 0;
    while index < args.len() {
        let arg = &args[index];
        if let Some(value) = npm_json_flag_value(arg) {
            json = value;
        } else if matches!(arg.as_str(), "--silent" | "-s" | "--long" | "--parseable") {
        } else if matches!(arg.as_str(), "--workspace" | "-w" | "--loglevel") {
            index += 1;
            if args.get(index).is_none() {
                return Err(OmcRegistryError::UnsupportedSpec(format!(
                    "{arg} needs a value"
                )));
            }
        } else if npm_explain_ignored_equals_flag(arg) {
        } else if arg.starts_with('-') {
            return Err(unsupported_compat_arg("npm explain", arg));
        } else {
            specs.push(arg.clone());
        }
        index += 1;
    }
    if specs.is_empty() {
        return Err(OmcRegistryError::UnsupportedSpec(
            "npm explain needs at least one package".to_owned(),
        ));
    }
    Ok(NpmCompatAction::Explain { specs, json })
}

fn npm_explain_ignored_equals_flag(arg: &str) -> bool {
    ["--workspace=", "--loglevel="]
        .iter()
        .any(|prefix| arg.starts_with(prefix))
}

fn parse_npm_outdated_args(args: &[String]) -> Result<NpmCompatAction, OmcRegistryError> {
    let mut json = false;
    let mut parseable = false;
    let mut filtered = Vec::new();
    let mut index = 0;
    while index < args.len() {
        let arg = &args[index];
        if let Some(value) = npm_json_flag_value(arg) {
            json = value;
        } else if matches!(arg.as_str(), "--parseable" | "-p") {
            parseable = true;
        } else if matches!(
            arg.as_str(),
            "--all"
                | "--long"
                | "--silent"
                | "-s"
                | "--global"
                | "-g"
                | "--dev"
                | "--prod"
                | "--production"
                | "--color=false"
        ) || npm_all_long_short_flag(arg)
        {
        } else if matches!(
            arg.as_str(),
            "--depth" | "--omit" | "--include" | "--loglevel" | "--userconfig"
        ) {
            index += 1;
            if args.get(index).is_none() {
                return Err(OmcRegistryError::UnsupportedSpec(format!(
                    "{arg} needs a value"
                )));
            }
        } else if npm_outdated_equals_value_flag(arg) {
        } else {
            filtered.push(arg.clone());
        }
        index += 1;
    }

    let CommonCompatFlags {
        npm_registry,
        positionals,
        ..
    } = parse_common_compat_flags(&filtered, true)?;

    Ok(NpmCompatAction::Outdated {
        json,
        parseable,
        packages: positionals,
        npm_registry,
    })
}

fn npm_outdated_equals_value_flag(arg: &str) -> bool {
    [
        "--depth=",
        "--omit=",
        "--include=",
        "--loglevel=",
        "--userconfig=",
    ]
    .iter()
    .any(|prefix| arg.starts_with(prefix))
}

fn npm_all_long_short_flag(arg: &str) -> bool {
    let Some(rest) = arg.strip_prefix('-') else {
        return false;
    };
    !rest.is_empty() && !rest.starts_with('-') && rest.chars().all(|ch| matches!(ch, 'a' | 'l'))
}

fn parse_npm_config_args(args: &[String]) -> Result<NpmCompatAction, OmcRegistryError> {
    let NpmConfigArgs {
        editor,
        json,
        location,
        npm_registry,
        userconfig,
        globalconfig,
        mut positionals,
    } = parse_npm_config_common_args(args)?;
    let command = if positionals.is_empty() {
        "list".to_owned()
    } else {
        positionals.remove(0)
    };
    match command.as_str() {
        "get" => {
            if positionals.is_empty() {
                return Err(OmcRegistryError::UnsupportedSpec(
                    "npm config get needs at least one key".to_owned(),
                ));
            }
            Ok(NpmCompatAction::Config {
                action: NpmConfigAction::Get {
                    keys: positionals,
                    json,
                    location,
                },
                npm_registry,
                userconfig,
                globalconfig,
            })
        }
        "list" | "ls" => {
            if !positionals.is_empty() {
                return Err(unsupported_compat_arg("npm config list", &positionals[0]));
            }
            Ok(NpmCompatAction::Config {
                action: NpmConfigAction::List { json, location },
                npm_registry,
                userconfig,
                globalconfig,
            })
        }
        "edit" => {
            if !positionals.is_empty() {
                return Err(unsupported_compat_arg("npm config edit", &positionals[0]));
            }
            Ok(NpmCompatAction::ConfigEdit {
                location,
                editor,
                userconfig,
                globalconfig,
            })
        }
        "set" => {
            let assignments = parse_npm_config_assignments(positionals)?;
            Ok(NpmCompatAction::Config {
                action: NpmConfigAction::Set {
                    assignments,
                    location,
                },
                npm_registry,
                userconfig,
                globalconfig,
            })
        }
        "delete" | "del" | "rm" | "unset" => {
            if positionals.is_empty() {
                return Err(OmcRegistryError::UnsupportedSpec(
                    "npm config delete needs at least one key".to_owned(),
                ));
            }
            Ok(NpmCompatAction::Config {
                action: NpmConfigAction::Delete {
                    keys: positionals,
                    location,
                },
                npm_registry,
                userconfig,
                globalconfig,
            })
        }
        other => Err(OmcRegistryError::UnsupportedSpec(format!(
            "unsupported npm config command `{other}`"
        ))),
    }
}

fn parse_npm_view_args(args: &[String]) -> Result<NpmCompatAction, OmcRegistryError> {
    let mut json = false;
    let mut filtered = Vec::new();
    let mut index = 0;
    while index < args.len() {
        let arg = &args[index];
        if let Some(value) = npm_json_flag_value(arg) {
            json = value;
        } else if matches!(arg.as_str(), "--userconfig" | "--loglevel") {
            index += 1;
            if args.get(index).is_none() {
                return Err(OmcRegistryError::UnsupportedSpec(format!(
                    "{arg} needs a value"
                )));
            }
        } else if matches!(arg.as_str(), "--silent" | "-s" | "--parseable" | "--long")
            || npm_view_equals_value_flag(arg)
        {
        } else {
            filtered.push(arg.clone());
        }
        index += 1;
    }

    let CommonCompatFlags {
        npm_registry,
        mut positionals,
        ..
    } = parse_common_compat_flags(&filtered, true)?;
    if positionals.is_empty() {
        return Err(OmcRegistryError::UnsupportedSpec(
            "npm view needs a package".to_owned(),
        ));
    }
    let spec = positionals.remove(0);
    Ok(NpmCompatAction::View {
        spec,
        fields: positionals,
        json,
        npm_registry,
    })
}

fn parse_npm_metadata_url_args(
    command: &str,
    kind: NpmMetadataUrlKind,
    args: &[String],
) -> Result<NpmCompatAction, OmcRegistryError> {
    let mut json = false;
    let mut filtered = Vec::new();
    let mut index = 0;
    while index < args.len() {
        let arg = &args[index];
        if arg == "--json" {
            json = true;
        } else if matches!(
            arg.as_str(),
            "--browser" | "--browser=true" | "--browser=false"
        ) {
        } else if matches!(arg.as_str(), "--userconfig" | "--loglevel") {
            index += 1;
            if args.get(index).is_none() {
                return Err(OmcRegistryError::UnsupportedSpec(format!(
                    "{arg} needs a value"
                )));
            }
        } else if matches!(arg.as_str(), "--silent" | "-s" | "--parseable")
            || npm_metadata_url_equals_value_flag(arg)
        {
        } else {
            filtered.push(arg.clone());
        }
        index += 1;
    }

    let CommonCompatFlags {
        npm_registry,
        mut positionals,
        ..
    } = parse_common_compat_flags(&filtered, true)?;
    if positionals.len() > 1 {
        return Err(unsupported_compat_arg(command, &positionals[1]));
    }
    Ok(NpmCompatAction::MetadataUrl {
        kind,
        spec: positionals.pop(),
        json,
        npm_registry,
    })
}

fn npm_metadata_url_equals_value_flag(arg: &str) -> bool {
    ["--browser=", "--userconfig=", "--loglevel="]
        .iter()
        .any(|prefix| arg.starts_with(prefix))
}

fn npm_view_equals_value_flag(arg: &str) -> bool {
    ["--userconfig=", "--loglevel="]
        .iter()
        .any(|prefix| arg.starts_with(prefix))
}

fn parse_npm_config_get_args(args: &[String]) -> Result<NpmCompatAction, OmcRegistryError> {
    let NpmConfigArgs {
        json,
        location,
        npm_registry,
        userconfig,
        globalconfig,
        positionals,
        ..
    } = parse_npm_config_common_args(args)?;
    if positionals.is_empty() {
        return Err(OmcRegistryError::UnsupportedSpec(
            "npm config get needs at least one key".to_owned(),
        ));
    }
    Ok(NpmCompatAction::Config {
        action: NpmConfigAction::Get {
            keys: positionals,
            json,
            location,
        },
        npm_registry,
        userconfig,
        globalconfig,
    })
}

fn parse_npm_config_set_args(args: &[String]) -> Result<NpmCompatAction, OmcRegistryError> {
    let NpmConfigArgs {
        location,
        npm_registry,
        userconfig,
        globalconfig,
        positionals,
        ..
    } = parse_npm_config_common_args(args)?;
    let assignments = parse_npm_config_assignments(positionals)?;
    Ok(NpmCompatAction::Config {
        action: NpmConfigAction::Set {
            assignments,
            location,
        },
        npm_registry,
        userconfig,
        globalconfig,
    })
}

fn parse_npm_config_assignments(
    positionals: Vec<String>,
) -> Result<Vec<(String, String)>, OmcRegistryError> {
    if positionals.is_empty() {
        return Err(OmcRegistryError::UnsupportedSpec(
            "npm config set needs a key and value".to_owned(),
        ));
    }
    if positionals.iter().any(|value| value.contains('=')) {
        return positionals
            .into_iter()
            .map(|assignment| {
                let Some((key, value)) = assignment.split_once('=') else {
                    return Err(OmcRegistryError::UnsupportedSpec(format!(
                        "npm config set mixed assignment formats at `{assignment}`"
                    )));
                };
                npm_config_assignment(key, value)
            })
            .collect();
    }
    if positionals.len() != 2 {
        return Err(OmcRegistryError::UnsupportedSpec(
            "npm config set needs either KEY VALUE or KEY=VALUE".to_owned(),
        ));
    }
    npm_config_assignment(&positionals[0], &positionals[1]).map(|assignment| vec![assignment])
}

fn npm_config_assignment(key: &str, value: &str) -> Result<(String, String), OmcRegistryError> {
    let key = key.trim();
    if key.is_empty() {
        return Err(OmcRegistryError::UnsupportedSpec(
            "npm config key cannot be empty".to_owned(),
        ));
    }
    Ok((key.to_owned(), value.trim().to_owned()))
}

#[derive(Debug)]
struct NpmConfigArgs {
    editor: Option<String>,
    json: bool,
    location: NpmConfigLocation,
    npm_registry: Option<String>,
    userconfig: Option<PathBuf>,
    globalconfig: Option<PathBuf>,
    positionals: Vec<String>,
}

fn parse_npm_config_common_args(args: &[String]) -> Result<NpmConfigArgs, OmcRegistryError> {
    let mut editor = None;
    let mut json = false;
    let mut location = NpmConfigLocation::User;
    let mut userconfig = None;
    let mut globalconfig = None;
    let mut filtered = Vec::new();
    let mut index = 0;
    while index < args.len() {
        let arg = &args[index];
        if arg == "--json" {
            json = true;
        } else if arg == "--userconfig" {
            index += 1;
            let Some(path) = args.get(index) else {
                return Err(OmcRegistryError::UnsupportedSpec(
                    "--userconfig needs a path".to_owned(),
                ));
            };
            userconfig = Some(PathBuf::from(path));
        } else if let Some(path) = arg.strip_prefix("--userconfig=") {
            userconfig = Some(PathBuf::from(path));
        } else if arg == "--globalconfig" {
            index += 1;
            let Some(path) = args.get(index) else {
                return Err(OmcRegistryError::UnsupportedSpec(
                    "--globalconfig needs a path".to_owned(),
                ));
            };
            globalconfig = Some(PathBuf::from(path));
        } else if let Some(path) = arg.strip_prefix("--globalconfig=") {
            globalconfig = Some(PathBuf::from(path));
        } else if matches!(arg.as_str(), "--global" | "-g") {
            location = NpmConfigLocation::Global;
        } else if arg == "--location" {
            index += 1;
            let Some(value) = args.get(index) else {
                return Err(OmcRegistryError::UnsupportedSpec(
                    "--location needs a value".to_owned(),
                ));
            };
            location = parse_npm_config_location(value)?;
        } else if let Some(value) = arg.strip_prefix("--location=") {
            location = parse_npm_config_location(value)?;
        } else if arg == "--editor" {
            index += 1;
            let Some(value) = args.get(index) else {
                return Err(OmcRegistryError::UnsupportedSpec(
                    "--editor needs a value".to_owned(),
                ));
            };
            editor = Some(value.clone());
        } else if let Some(value) = arg.strip_prefix("--editor=") {
            editor = Some(value.to_owned());
        } else if matches!(arg.as_str(), "--long" | "-l" | "--parseable") {
        } else {
            filtered.push(arg.clone());
        }
        index += 1;
    }

    let CommonCompatFlags {
        npm_registry,
        positionals,
        ..
    } = parse_common_compat_flags(&filtered, true)?;
    Ok(NpmConfigArgs {
        editor,
        json,
        location,
        npm_registry,
        userconfig,
        globalconfig,
        positionals,
    })
}

fn parse_npm_config_location(value: &str) -> Result<NpmConfigLocation, OmcRegistryError> {
    match value {
        "user" => Ok(NpmConfigLocation::User),
        "project" => Ok(NpmConfigLocation::Project),
        "global" => Ok(NpmConfigLocation::Global),
        other => Err(OmcRegistryError::UnsupportedSpec(format!(
            "unsupported npm config location `{other}`"
        ))),
    }
}

fn npm_audit_equals_value_flag(arg: &str) -> bool {
    ["--audit-level=", "--audit-levels="]
        .iter()
        .any(|prefix| arg.starts_with(prefix))
}

#[derive(Debug, PartialEq, Eq)]
struct NpmRunArgs {
    name: Option<String>,
    args: Vec<String>,
    if_present: bool,
    json: bool,
    workspaces: Vec<String>,
    all_workspaces: bool,
    include_workspace_root: bool,
}

fn parse_npm_run_args(
    command: &str,
    args: &[String],
    implicit_name: Option<&str>,
) -> Result<NpmRunArgs, OmcRegistryError> {
    let mut name = implicit_name.map(str::to_owned);
    let mut script_args = Vec::new();
    let mut if_present = false;
    let mut json = false;
    let mut workspaces = Vec::new();
    let mut all_workspaces = false;
    let mut include_workspace_root = false;
    let mut index = 0;
    while index < args.len() {
        let arg = &args[index];
        if arg == "--" {
            script_args.extend(args[index + 1..].iter().cloned());
            break;
        } else if matches!(
            arg.as_str(),
            "--if-present" | "--silent" | "-s" | "--loglevel=silent"
        ) {
            if arg == "--if-present" {
                if_present = true;
            }
        } else if arg == "--json" || arg == "--json=true" {
            json = true;
        } else if arg == "--json=false" {
            json = false;
        } else if let Some(value) = npm_all_workspaces_flag_value(arg) {
            all_workspaces = value;
        } else if let Some(value) = npm_include_workspace_root_flag_value(arg) {
            include_workspace_root = value;
        } else if matches!(arg.as_str(), "--workspace" | "-w") {
            index += 1;
            let Some(workspace) = args.get(index) else {
                return Err(OmcRegistryError::UnsupportedSpec(format!(
                    "{arg} needs a workspace"
                )));
            };
            workspaces.push(workspace.clone());
        } else if let Some(workspace) = arg
            .strip_prefix("--workspace=")
            .or_else(|| arg.strip_prefix("-w="))
        {
            workspaces.push(workspace.to_owned());
        } else if let Some(workspace) = npm_attached_short_value(arg, 'w') {
            workspaces.push(workspace.to_owned());
        } else if arg == "--loglevel" {
            index += 1;
            if args.get(index).is_none() {
                return Err(OmcRegistryError::UnsupportedSpec(format!(
                    "{arg} needs a value"
                )));
            }
        } else if npm_run_equals_value_flag(arg) {
        } else if name.is_none() && !arg.starts_with('-') {
            name = Some(arg.clone());
        } else if name.is_some() {
            script_args.push(arg.clone());
        } else {
            return Err(unsupported_compat_arg(command, arg));
        }
        index += 1;
    }

    if name.is_none() && !script_args.is_empty() {
        return Err(OmcRegistryError::UnsupportedSpec(format!(
            "{command} needs a target"
        )));
    }
    Ok(NpmRunArgs {
        name,
        args: script_args,
        if_present,
        json,
        workspaces,
        all_workspaces,
        include_workspace_root,
    })
}

fn npm_run_equals_value_flag(arg: &str) -> bool {
    ["--loglevel=", "--include-workspace-root="]
        .iter()
        .any(|prefix| arg.starts_with(prefix))
}

fn parse_npm_exec_args(
    command_name: &str,
    args: &[String],
) -> Result<NpmExecAction, OmcRegistryError> {
    let mut packages = Vec::new();
    let mut no_install = false;
    let mut npm_registry = None;
    let mut allow = Vec::new();
    let mut allow_flow = Vec::new();
    let mut allow_all_host = false;
    let mut workspaces = Vec::new();
    let mut all_workspaces = false;
    let mut include_workspace_root = false;
    let mut call = None;
    let mut filtered = Vec::new();
    let mut index = 0;
    while index < args.len() {
        let arg = &args[index];
        if arg == "--" {
            filtered.extend(args[index + 1..].iter().cloned());
            break;
        } else if matches!(
            arg.as_str(),
            "-y" | "--yes"
                | "--no"
                | "--ignore-existing"
                | "--foreground-scripts"
                | "--quiet"
                | "--silent"
        ) {
        } else if arg == "--no-install" {
            no_install = true;
        } else if matches!(arg.as_str(), "-c" | "--call") {
            index += 1;
            let Some(value) = args.get(index) else {
                return Err(OmcRegistryError::UnsupportedSpec(format!(
                    "{arg} needs a command"
                )));
            };
            call = Some(value.clone());
        } else if let Some(value) = arg.strip_prefix("--call=") {
            call = Some(value.to_owned());
        } else if matches!(arg.as_str(), "-p" | "--package") {
            index += 1;
            let Some(package) = args.get(index) else {
                return Err(OmcRegistryError::UnsupportedSpec(format!(
                    "{arg} needs a value"
                )));
            };
            packages.push(package.clone());
        } else if let Some(package) = arg.strip_prefix("--package=") {
            packages.push(package.to_owned());
        } else if arg == "--registry" {
            index += 1;
            let Some(registry) = args.get(index) else {
                return Err(OmcRegistryError::UnsupportedSpec(
                    "--registry needs a URL".to_owned(),
                ));
            };
            npm_registry = Some(registry.clone());
        } else if let Some(registry) = arg.strip_prefix("--registry=") {
            npm_registry = Some(registry.to_owned());
        } else if arg == "--allow" {
            index += 1;
            let Some(grant) = args.get(index) else {
                return Err(OmcRegistryError::UnsupportedSpec(
                    "--allow needs a capability grant".to_owned(),
                ));
            };
            allow.push(grant.clone());
        } else if let Some(grant) = arg.strip_prefix("--allow=") {
            allow.push(grant.to_owned());
        } else if arg == "--allow-flow" {
            index += 1;
            let Some(flow) = args.get(index) else {
                return Err(OmcRegistryError::UnsupportedSpec(
                    "--allow-flow needs a data-flow grant".to_owned(),
                ));
            };
            allow_flow.push(flow.clone());
        } else if let Some(flow) = arg.strip_prefix("--allow-flow=") {
            allow_flow.push(flow.to_owned());
        } else if arg == "--allow-all-host" {
            allow_all_host = true;
        } else if let Some(value) = npm_all_workspaces_flag_value(arg) {
            all_workspaces = value;
        } else if let Some(value) = npm_include_workspace_root_flag_value(arg) {
            include_workspace_root = value;
        } else if matches!(arg.as_str(), "--workspace" | "-w") {
            index += 1;
            let Some(workspace) = args.get(index) else {
                return Err(OmcRegistryError::UnsupportedSpec(format!(
                    "{arg} needs a workspace"
                )));
            };
            workspaces.push(workspace.clone());
        } else if let Some(workspace) = arg
            .strip_prefix("--workspace=")
            .or_else(|| arg.strip_prefix("-w="))
        {
            workspaces.push(workspace.to_owned());
        } else if let Some(workspace) = npm_attached_short_value(arg, 'w') {
            workspaces.push(workspace.to_owned());
        } else if ignored_npm_install_preference_flag(arg) {
        } else if matches!(arg.as_str(), "--cache" | "--userconfig" | "--loglevel") {
            index += 1;
            if args.get(index).is_none() {
                return Err(OmcRegistryError::UnsupportedSpec(format!(
                    "{arg} needs a value"
                )));
            }
        } else if npm_exec_equals_value_flag(arg) {
        } else if arg.starts_with('-') {
            return Err(unsupported_compat_arg("npm exec", arg));
        } else {
            filtered.push(arg.clone());
            filtered.extend(args[index + 1..].iter().cloned());
            break;
        }
        index += 1;
    }
    let (command, args, prefer_project_bin) = if let Some(call) = call {
        if let Some(extra) = filtered.first() {
            return Err(unsupported_compat_arg("npm exec", extra));
        }
        let (command, args) = npm_exec_call_command(call);
        (command, args, false)
    } else {
        let (mut command, args) = split_first_position("npm exec", &filtered)?;
        let direct_package_command =
            packages.is_empty() && !no_install && npm_exec_direct_package_arg(&command);
        let prefer_project_bin = direct_package_command
            || (command_name == "npx"
                && packages.is_empty()
                && !no_install
                && npm_exec_should_infer_package(&command));
        if direct_package_command {
            packages.push(command.clone());
        } else if prefer_project_bin {
            let package = command.clone();
            command = npm_exec_inferred_bin_name(&package)?;
            packages.push(package);
        }
        (command, args, prefer_project_bin)
    };
    Ok(NpmExecAction {
        packages,
        command,
        args,
        no_install,
        prefer_project_bin,
        npm_registry,
        allow,
        allow_flow,
        allow_all_host,
        workspaces,
        all_workspaces,
        include_workspace_root,
    })
}

#[cfg(windows)]
fn npm_exec_call_command(call: String) -> (String, Vec<String>) {
    ("cmd".to_owned(), vec!["/C".to_owned(), call])
}

#[cfg(not(windows))]
fn npm_exec_call_command(call: String) -> (String, Vec<String>) {
    ("sh".to_owned(), vec!["-c".to_owned(), call])
}

fn npm_exec_equals_value_flag(arg: &str) -> bool {
    ["--cache=", "--userconfig=", "--loglevel="]
        .iter()
        .any(|prefix| arg.starts_with(prefix))
        || ignored_npm_install_preference_equals_flag(arg)
}

fn npm_exec_should_infer_package(command: &str) -> bool {
    !command.is_empty()
        && !command.starts_with("./")
        && !command.starts_with("../")
        && !Path::new(command).is_absolute()
        && !command.contains('\\')
}

fn npm_exec_inferred_bin_name(package: &str) -> Result<String, OmcRegistryError> {
    let package = package.strip_prefix("npm:").unwrap_or(package);
    let (name, _) = npm_create_split_version(package)?;
    Ok(npm_package_bin_name(name).to_owned())
}

fn parse_npm_explore_args(args: &[String]) -> Result<NpmCompatAction, OmcRegistryError> {
    let mut package = None;
    let mut command = None;
    let mut command_args = Vec::new();
    let mut shell = None;
    let mut index = 0;
    while index < args.len() {
        let arg = &args[index];
        if arg == "--" {
            let Some(command_arg) = args.get(index + 1) else {
                return Err(OmcRegistryError::UnsupportedSpec(
                    "npm explore -- needs a command".to_owned(),
                ));
            };
            command = Some(command_arg.clone());
            command_args.extend(args[index + 2..].iter().cloned());
            break;
        } else if matches!(arg.as_str(), "--silent" | "-s" | "--parseable" | "-p") {
        } else if arg == "--shell" {
            index += 1;
            let Some(value) = args.get(index) else {
                return Err(OmcRegistryError::UnsupportedSpec(
                    "--shell needs a value".to_owned(),
                ));
            };
            shell = Some(value.clone());
        } else if let Some(value) = arg.strip_prefix("--shell=") {
            shell = Some(value.to_owned());
        } else if matches!(arg.as_str(), "--loglevel" | "--cache" | "--registry") {
            index += 1;
            if args.get(index).is_none() {
                return Err(OmcRegistryError::UnsupportedSpec(format!(
                    "{arg} needs a value"
                )));
            }
        } else if npm_explore_equals_value_flag(arg) {
        } else if arg.starts_with('-') {
            return Err(unsupported_compat_arg("npm explore", arg));
        } else if package.is_none() {
            package = Some(arg.clone());
        } else {
            return Err(OmcRegistryError::UnsupportedSpec(
                "npm explore accepts one package before --".to_owned(),
            ));
        }
        index += 1;
    }

    let Some(package) = package else {
        return Err(OmcRegistryError::UnsupportedSpec(
            "npm explore needs a package name".to_owned(),
        ));
    };
    Ok(NpmCompatAction::Explore {
        action: NpmExploreAction {
            package,
            command,
            args: command_args,
            shell,
        },
    })
}

fn npm_explore_equals_value_flag(arg: &str) -> bool {
    ["--shell=", "--loglevel=", "--cache=", "--registry="]
        .iter()
        .any(|prefix| arg.starts_with(prefix))
}

fn parse_npm_edit_args(args: &[String]) -> Result<NpmCompatAction, OmcRegistryError> {
    let mut editor = None;
    let mut positionals = Vec::new();
    let mut index = 0;
    while index < args.len() {
        let arg = &args[index];
        if arg == "--editor" {
            index += 1;
            let Some(value) = args.get(index) else {
                return Err(OmcRegistryError::UnsupportedSpec(
                    "--editor needs a value".to_owned(),
                ));
            };
            editor = Some(value.clone());
        } else if let Some(value) = arg.strip_prefix("--editor=") {
            editor = Some(value.to_owned());
        } else if matches!(arg.as_str(), "--loglevel" | "--cache" | "--registry") {
            index += 1;
            if args.get(index).is_none() {
                return Err(OmcRegistryError::UnsupportedSpec(format!(
                    "{arg} needs a value"
                )));
            }
        } else if npm_edit_equals_value_flag(arg) {
        } else if arg.starts_with('-') {
            return Err(unsupported_compat_arg("npm edit", arg));
        } else {
            positionals.push(arg.clone());
        }
        index += 1;
    }

    match positionals.as_slice() {
        [] => Err(OmcRegistryError::UnsupportedSpec(
            "npm edit needs a package".to_owned(),
        )),
        [target] => Ok(NpmCompatAction::Edit {
            target: target.clone(),
            editor,
        }),
        [_, extra, ..] => Err(unsupported_compat_arg("npm edit", extra)),
    }
}

fn npm_edit_equals_value_flag(arg: &str) -> bool {
    ["--editor=", "--loglevel=", "--cache=", "--registry="]
        .iter()
        .any(|prefix| arg.starts_with(prefix))
}

fn parse_pip_compat_action(args: &[String]) -> Result<PipCompatAction, OmcRegistryError> {
    let normalized = normalize_pip_global_args(args)?;
    let args = normalized.as_slice();
    if let Some(action) = parse_pip_help_request(args) {
        return Ok(action);
    }
    let Some(command) = args.first().map(String::as_str) else {
        return Err(OmcRegistryError::UnsupportedSpec(
            "pip compatibility needs a command such as install, uninstall, freeze, or list"
                .to_owned(),
        ));
    };

    match command {
        "--version" | "-V" => Ok(PipCompatAction::Version),
        "completion" => parse_pip_completion_args(&args[1..]),
        "install" => parse_pip_install_args(&args[1..]),
        "lock" => parse_pip_lock_args(&args[1..]),
        "download" => parse_pip_download_args(&args[1..]),
        "wheel" => parse_pip_wheel_args(&args[1..]),
        "uninstall" | "remove" => parse_pip_uninstall_args(&args[1..]),
        "show" => parse_pip_show_args(&args[1..]),
        "hash" => parse_pip_hash_args(&args[1..]),
        "cache" => parse_pip_cache_args(&args[1..]),
        "check" => parse_pip_check_args(&args[1..]),
        "debug" => parse_pip_debug_args(&args[1..]),
        "inspect" => parse_pip_inspect_args(&args[1..]),
        "freeze" => {
            let action = parse_pip_freeze_args(&args[1..])?;
            Ok(PipCompatAction::Freeze { action })
        }
        "list" => parse_pip_list_args(&args[1..]),
        "index" => parse_pip_index_args(&args[1..]),
        "search" => parse_pip_search_args(&args[1..]),
        "config" => parse_pip_config_args(&args[1..]),
        other => Err(OmcRegistryError::UnsupportedSpec(format!(
            "unsupported pip compatibility command `{other}`"
        ))),
    }
}

fn parse_twine_compat_action(args: &[String]) -> Result<TwineCompatAction, OmcRegistryError> {
    let normalized = normalize_twine_global_args(args)?;
    let args = normalized.as_slice();
    if let Some(action) = parse_twine_help_request(args) {
        return Ok(action);
    }
    let Some(command) = args.first().map(String::as_str) else {
        return Err(OmcRegistryError::UnsupportedSpec(
            "twine compatibility needs a command such as check or upload".to_owned(),
        ));
    };

    match command {
        "--version" | "-V" => Ok(TwineCompatAction::Version),
        "check" => parse_twine_check_args(&args[1..]),
        "upload" => parse_twine_upload_args(&args[1..]),
        other => Err(OmcRegistryError::UnsupportedSpec(format!(
            "unsupported twine compatibility command `{other}`"
        ))),
    }
}

fn parse_twine_help_request(args: &[String]) -> Option<TwineCompatAction> {
    let command = args.first()?;
    if twine_help_flag(command) {
        return Some(TwineCompatAction::Help { topic: None });
    }
    if command == "help" {
        let topic = args
            .iter()
            .skip(1)
            .find(|arg| !arg.starts_with('-'))
            .cloned();
        return Some(TwineCompatAction::Help { topic });
    }
    if args
        .iter()
        .take_while(|arg| arg.as_str() != "--")
        .any(|arg| twine_help_flag(arg))
    {
        return Some(TwineCompatAction::Help {
            topic: Some(command.clone()),
        });
    }
    None
}

fn twine_help_flag(arg: &str) -> bool {
    matches!(arg, "--help" | "-h")
}

fn normalize_twine_global_args(args: &[String]) -> Result<Vec<String>, OmcRegistryError> {
    let mut index = 0;
    while index < args.len() {
        let arg = &args[index];
        if matches!(arg.as_str(), "--version" | "-V") {
            return Ok(vec![arg.clone()]);
        } else if matches!(arg.as_str(), "--no-color" | "--no-input") {
        } else if arg.starts_with('-') {
            return Ok(args[index..].to_vec());
        } else if index == 0 {
            return Ok(args.to_vec());
        } else {
            return Ok(args[index..].to_vec());
        }
        index += 1;
    }
    Ok(Vec::new())
}

fn parse_twine_check_args(args: &[String]) -> Result<TwineCompatAction, OmcRegistryError> {
    let mut paths = Vec::new();
    let mut strict = false;
    let mut index = 0;
    while index < args.len() {
        let arg = &args[index];
        if twine_help_flag(arg) {
            return Ok(TwineCompatAction::Help {
                topic: Some("check".to_owned()),
            });
        } else if arg == "--strict" {
            strict = true;
        } else if matches!(
            arg.as_str(),
            "--non-interactive" | "--disable-progress-bar" | "--verbose"
        ) {
        } else if arg.starts_with('-') {
            return Err(unsupported_compat_arg("twine check", arg));
        } else {
            paths.push(PathBuf::from(arg));
        }
        index += 1;
    }
    Ok(TwineCompatAction::Check(TwineCheckAction { paths, strict }))
}

fn parse_twine_upload_args(args: &[String]) -> Result<TwineCompatAction, OmcRegistryError> {
    let mut paths = Vec::new();
    let mut repository = None;
    let mut repository_url = None;
    let mut username = None;
    let mut password = None;
    let mut config_file = None;
    let mut cert = None;
    let mut client_cert = None;
    let mut skip_existing = false;
    let mut comment = None;
    let mut sign = false;
    let mut sign_with = None;
    let mut identity = None;
    let mut attestations = false;
    let mut index = 0;
    while index < args.len() {
        let arg = &args[index];
        if twine_help_flag(arg) {
            return Ok(TwineCompatAction::Help {
                topic: Some("upload".to_owned()),
            });
        } else if arg == "-r" || arg == "--repository" {
            index += 1;
            repository = Some(twine_flag_value(args, index, arg)?);
        } else if let Some(value) = arg.strip_prefix("--repository=") {
            repository = Some(value.to_owned());
        } else if arg == "--repository-url" {
            index += 1;
            repository_url = Some(twine_flag_value(args, index, arg)?);
        } else if let Some(value) = arg.strip_prefix("--repository-url=") {
            repository_url = Some(value.to_owned());
        } else if arg == "-u" || arg == "--username" {
            index += 1;
            username = Some(twine_flag_value(args, index, arg)?);
        } else if let Some(value) = arg.strip_prefix("--username=") {
            username = Some(value.to_owned());
        } else if arg == "-p" || arg == "--password" {
            index += 1;
            password = Some(twine_flag_value(args, index, arg)?);
        } else if let Some(value) = arg.strip_prefix("--password=") {
            password = Some(value.to_owned());
        } else if arg == "--config-file" {
            index += 1;
            config_file = Some(PathBuf::from(twine_flag_value(args, index, arg)?));
        } else if let Some(value) = arg.strip_prefix("--config-file=") {
            config_file = Some(PathBuf::from(value));
        } else if arg == "--cert" {
            index += 1;
            cert = Some(PathBuf::from(twine_flag_value(args, index, arg)?));
        } else if let Some(value) = arg.strip_prefix("--cert=") {
            cert = Some(PathBuf::from(value));
        } else if arg == "--client-cert" {
            index += 1;
            client_cert = Some(PathBuf::from(twine_flag_value(args, index, arg)?));
        } else if let Some(value) = arg.strip_prefix("--client-cert=") {
            client_cert = Some(PathBuf::from(value));
        } else if arg == "-c" || arg == "--comment" {
            index += 1;
            comment = Some(twine_flag_value(args, index, arg)?);
        } else if let Some(value) = arg.strip_prefix("--comment=") {
            comment = Some(value.to_owned());
        } else if arg == "--skip-existing" {
            skip_existing = true;
        } else if matches!(
            arg.as_str(),
            "--non-interactive" | "--disable-progress-bar" | "--verbose"
        ) {
        } else if matches!(arg.as_str(), "-s" | "--sign") {
            sign = true;
        } else if arg == "--sign-with" {
            index += 1;
            sign_with = Some(twine_flag_value(args, index, arg)?);
        } else if let Some(value) = arg.strip_prefix("--sign-with=") {
            sign_with = Some(value.to_owned());
        } else if arg == "-i" || arg == "--identity" {
            index += 1;
            identity = Some(twine_flag_value(args, index, arg)?);
        } else if let Some(value) = arg.strip_prefix("--identity=") {
            identity = Some(value.to_owned());
        } else if arg == "--attestations" {
            attestations = true;
        } else if arg.starts_with('-') {
            return Err(unsupported_compat_arg("twine upload", arg));
        } else {
            paths.push(PathBuf::from(arg));
        }
        index += 1;
    }
    Ok(TwineCompatAction::Upload(Box::new(TwineUploadAction {
        paths,
        repository,
        repository_url,
        username,
        password,
        config_file,
        cert,
        client_cert,
        skip_existing,
        comment,
        sign,
        sign_with,
        identity,
        attestations,
    })))
}

fn twine_flag_value(args: &[String], index: usize, flag: &str) -> Result<String, OmcRegistryError> {
    args.get(index)
        .cloned()
        .ok_or_else(|| OmcRegistryError::UnsupportedSpec(format!("{flag} needs a value")))
}

fn parse_pip_help_request(args: &[String]) -> Option<PipCompatAction> {
    let command = args.first()?;
    if pip_help_flag(command) {
        return Some(PipCompatAction::Help { topic: None });
    }
    if command == "help" {
        let topic = args
            .iter()
            .skip(1)
            .find(|arg| !arg.starts_with('-'))
            .cloned();
        return Some(PipCompatAction::Help { topic });
    }
    if args
        .iter()
        .take_while(|arg| arg.as_str() != "--")
        .any(|arg| pip_help_flag(arg))
    {
        return Some(PipCompatAction::Help {
            topic: Some(command.clone()),
        });
    }
    None
}

fn pip_help_flag(arg: &str) -> bool {
    matches!(arg, "--help" | "-h")
}

fn parse_pip_completion_args(args: &[String]) -> Result<PipCompatAction, OmcRegistryError> {
    let mut shell = None;
    let mut index = 0;
    while index < args.len() {
        let arg = &args[index];
        if arg == "--bash" {
            shell = Some(PipCompletionShell::Bash);
        } else if arg == "--zsh" {
            shell = Some(PipCompletionShell::Zsh);
        } else if arg == "--fish" {
            shell = Some(PipCompletionShell::Fish);
        } else if matches!(
            arg.as_str(),
            "--disable-pip-version-check" | "--no-color" | "--no-input" | "--isolated"
        ) {
        } else if matches!(
            arg.as_str(),
            "--log" | "--proxy" | "--retries" | "--timeout"
        ) {
            index += 1;
            if args.get(index).is_none() {
                return Err(OmcRegistryError::UnsupportedSpec(format!(
                    "{arg} needs a value"
                )));
            }
        } else if pip_completion_ignored_equals_flag(arg) {
        } else {
            return Err(unsupported_compat_arg("pip completion", arg));
        }
        index += 1;
    }
    Ok(PipCompatAction::Completion { shell })
}

fn pip_completion_ignored_equals_flag(arg: &str) -> bool {
    ["--log=", "--proxy=", "--retries=", "--timeout="]
        .iter()
        .any(|prefix| arg.starts_with(prefix))
}

fn normalize_pip_global_args(args: &[String]) -> Result<Vec<String>, OmcRegistryError> {
    let mut index = 0;
    while index < args.len() {
        let arg = &args[index];
        if matches!(arg.as_str(), "--version" | "-V") {
            return Ok(vec![arg.clone()]);
        } else if pip_global_ignored_bool_flag(arg) || pip_global_ignored_equals_flag(arg) {
        } else if pip_global_ignored_value_flag(arg) {
            index += 1;
            if args.get(index).is_none() {
                return Err(OmcRegistryError::UnsupportedSpec(format!(
                    "{arg} needs a value"
                )));
            }
        } else if arg.starts_with('-') {
            return Ok(args[index..].to_vec());
        } else if index == 0 {
            return Ok(args.to_vec());
        } else {
            return Ok(args[index..].to_vec());
        }
        index += 1;
    }
    Ok(Vec::new())
}

fn pip_global_ignored_bool_flag(arg: &str) -> bool {
    pip_ignored_verbosity_flag(arg)
        || matches!(
            arg,
            "--disable-pip-version-check"
                | "--no-cache-dir"
                | "--isolated"
                | "--require-virtualenv"
                | "--no-color"
                | "--no-input"
                | "--no-python-version-warning"
        )
}

fn pip_ignored_verbosity_flag(arg: &str) -> bool {
    matches!(arg, "-q" | "--quiet" | "-v" | "--verbose")
        || pip_repeated_short_flag(arg, 'q')
        || pip_repeated_short_flag(arg, 'v')
}

fn pip_verbose_flag(arg: &str) -> bool {
    matches!(arg, "-v" | "--verbose") || pip_repeated_short_flag(arg, 'v')
}

fn pip_repeated_short_flag(arg: &str, flag: char) -> bool {
    let Some(rest) = arg.strip_prefix('-') else {
        return false;
    };
    rest.len() > 1 && !rest.starts_with('-') && rest.chars().all(|ch| ch == flag)
}

fn pip_global_ignored_value_flag(arg: &str) -> bool {
    matches!(
        arg,
        "--log"
            | "--proxy"
            | "--retries"
            | "--timeout"
            | "--exists-action"
            | "--trusted-host"
            | "--cert"
            | "--client-cert"
            | "--cache-dir"
            | "--use-feature"
            | "--use-deprecated"
    )
}

fn pip_global_ignored_equals_flag(arg: &str) -> bool {
    [
        "--log=",
        "--proxy=",
        "--retries=",
        "--timeout=",
        "--exists-action=",
        "--trusted-host=",
        "--cert=",
        "--client-cert=",
        "--cache-dir=",
        "--use-feature=",
        "--use-deprecated=",
    ]
    .iter()
    .any(|prefix| arg.starts_with(prefix))
}

fn parse_pip_index_args(args: &[String]) -> Result<PipCompatAction, OmcRegistryError> {
    let PipIndexArgs {
        index_url,
        extra_index_urls,
        find_links,
        no_index,
        allow_prereleases,
        release_controls,
        uploaded_prior_to,
        compatibility,
        json,
        mut positionals,
    } = parse_pip_index_common_args(args)?;
    if positionals.is_empty() {
        return Err(OmcRegistryError::UnsupportedSpec(
            "pip index needs a command such as versions".to_owned(),
        ));
    }
    let command = positionals.remove(0);
    match command.as_str() {
        "versions" => {
            if positionals.len() != 1 {
                return Err(OmcRegistryError::UnsupportedSpec(
                    "pip index versions needs exactly one package".to_owned(),
                ));
            }
            Ok(PipCompatAction::IndexVersions {
                package: positionals.remove(0),
                index_url,
                extra_index_urls,
                find_links,
                no_index,
                allow_prereleases,
                release_controls,
                uploaded_prior_to,
                compatibility,
                json,
            })
        }
        other => Err(OmcRegistryError::UnsupportedSpec(format!(
            "unsupported pip index command `{other}`"
        ))),
    }
}

#[derive(Debug)]
struct PipIndexArgs {
    index_url: Option<String>,
    extra_index_urls: Vec<String>,
    find_links: Vec<String>,
    no_index: bool,
    allow_prereleases: bool,
    release_controls: PypiReleaseControls,
    uploaded_prior_to: Option<String>,
    compatibility: PipCompatibilityTarget,
    json: bool,
    positionals: Vec<String>,
}

fn parse_pip_index_common_args(args: &[String]) -> Result<PipIndexArgs, OmcRegistryError> {
    let mut parsed = PipIndexArgs {
        index_url: None,
        extra_index_urls: Vec::new(),
        find_links: Vec::new(),
        no_index: false,
        allow_prereleases: false,
        release_controls: PypiReleaseControls::default(),
        uploaded_prior_to: None,
        compatibility: PipCompatibilityTarget::default(),
        json: false,
        positionals: Vec::new(),
    };
    let mut index = 0;
    while index < args.len() {
        let arg = &args[index];
        if arg == "--json" {
            parsed.json = true;
        } else if arg == "-i" || arg == "--index-url" {
            index += 1;
            let Some(url) = args.get(index) else {
                return Err(OmcRegistryError::UnsupportedSpec(format!(
                    "{arg} needs a URL"
                )));
            };
            parsed.index_url = Some(url.clone());
        } else if let Some(url) = arg.strip_prefix("--index-url=") {
            parsed.index_url = Some(url.to_owned());
        } else if let Some(url) = pip_attached_short_value(arg, 'i') {
            parsed.index_url = Some(url.to_owned());
        } else if arg == "--extra-index-url" {
            index += 1;
            let Some(url) = args.get(index) else {
                return Err(OmcRegistryError::UnsupportedSpec(format!(
                    "{arg} needs a URL"
                )));
            };
            parsed.extra_index_urls.push(url.clone());
        } else if let Some(url) = arg.strip_prefix("--extra-index-url=") {
            parsed.extra_index_urls.push(url.to_owned());
        } else if arg == "-f" || arg == "--find-links" {
            index += 1;
            let Some(value) = args.get(index) else {
                return Err(OmcRegistryError::UnsupportedSpec(format!(
                    "{arg} needs a path or URL"
                )));
            };
            parsed.find_links.push(value.clone());
        } else if let Some(value) = arg.strip_prefix("--find-links=") {
            parsed.find_links.push(value.to_owned());
        } else if let Some(value) = pip_attached_short_value(arg, 'f') {
            parsed.find_links.push(value.to_owned());
        } else if let Some(value) = pip_bool_flag_value(arg, "--no-index") {
            parsed.no_index = value;
        } else if let Some(value) = pip_bool_flag_value(arg, "--pre") {
            parsed.allow_prereleases = value;
        } else if arg == "--all-releases" {
            let value = pip_target_flag_value(args, &mut index, arg)?;
            apply_pypi_release_control(&mut parsed.release_controls.all_releases, &value);
        } else if let Some(value) = arg.strip_prefix("--all-releases=") {
            apply_pypi_release_control(&mut parsed.release_controls.all_releases, value);
        } else if arg == "--only-final" {
            let value = pip_target_flag_value(args, &mut index, arg)?;
            apply_pypi_release_control(&mut parsed.release_controls.only_final, &value);
        } else if let Some(value) = arg.strip_prefix("--only-final=") {
            apply_pypi_release_control(&mut parsed.release_controls.only_final, value);
        } else if arg == "--uploaded-prior-to" {
            parsed.uploaded_prior_to = Some(pip_target_flag_value(args, &mut index, arg)?);
        } else if let Some(value) = arg.strip_prefix("--uploaded-prior-to=") {
            parsed.uploaded_prior_to = Some(value.to_owned());
        } else if arg == "--platform" {
            parsed
                .compatibility
                .platforms
                .push(pip_target_flag_value(args, &mut index, arg)?);
        } else if let Some(value) = arg.strip_prefix("--platform=") {
            parsed.compatibility.platforms.push(value.to_owned());
        } else if arg == "--python-version" {
            parsed.compatibility.python_version =
                Some(pip_target_flag_value(args, &mut index, arg)?);
        } else if let Some(value) = arg.strip_prefix("--python-version=") {
            parsed.compatibility.python_version = Some(value.to_owned());
        } else if arg == "--implementation" {
            parsed.compatibility.implementation =
                Some(pip_target_flag_value(args, &mut index, arg)?);
        } else if let Some(value) = arg.strip_prefix("--implementation=") {
            parsed.compatibility.implementation = Some(value.to_owned());
        } else if arg == "--abi" {
            parsed
                .compatibility
                .abis
                .push(pip_target_flag_value(args, &mut index, arg)?);
        } else if let Some(value) = arg.strip_prefix("--abi=") {
            parsed.compatibility.abis.push(value.to_owned());
        } else if matches!(
            arg.as_str(),
            "--disable-pip-version-check"
                | "--isolated"
                | "--no-cache-dir"
                | "--ignore-requires-python"
        ) || pip_ignored_verbosity_flag(arg)
        {
        } else if pip_index_ignored_value_flag(arg) {
            index += 1;
            if args.get(index).is_none() {
                return Err(OmcRegistryError::UnsupportedSpec(format!(
                    "{arg} needs a value"
                )));
            }
        } else if pip_index_ignored_equals_flag(arg) {
        } else if arg.starts_with('-') {
            return Err(unsupported_compat_arg("pip index", arg));
        } else {
            parsed.positionals.push(arg.clone());
        }
        index += 1;
    }
    Ok(parsed)
}

fn pip_index_ignored_value_flag(arg: &str) -> bool {
    matches!(
        arg,
        "--trusted-host"
            | "--timeout"
            | "--retries"
            | "--cert"
            | "--client-cert"
            | "--proxy"
            | "--cache-dir"
            | "--log"
    )
}

fn pip_index_ignored_equals_flag(arg: &str) -> bool {
    [
        "--trusted-host=",
        "--timeout=",
        "--retries=",
        "--cert=",
        "--client-cert=",
        "--proxy=",
        "--cache-dir=",
        "--log=",
    ]
    .iter()
    .any(|prefix| arg.starts_with(prefix))
}

fn parse_pip_search_args(args: &[String]) -> Result<PipCompatAction, OmcRegistryError> {
    let mut query = Vec::new();
    let mut index = 0;
    while index < args.len() {
        let arg = &args[index];
        if matches!(
            arg.as_str(),
            "--isolated"
                | "--disable-pip-version-check"
                | "--no-cache-dir"
                | "--no-color"
                | "--no-input"
                | "--no-python-version-warning"
        ) || pip_ignored_verbosity_flag(arg)
        {
        } else if matches!(
            arg.as_str(),
            "-i" | "--index"
                | "--log"
                | "--proxy"
                | "--retries"
                | "--timeout"
                | "--exists-action"
                | "--trusted-host"
                | "--cert"
                | "--client-cert"
                | "--cache-dir"
                | "--use-feature"
                | "--use-deprecated"
        ) {
            index += 1;
            if args.get(index).is_none() {
                return Err(OmcRegistryError::UnsupportedSpec(format!(
                    "{arg} needs a value"
                )));
            }
        } else if pip_search_ignored_equals_flag(arg) {
        } else if arg.starts_with('-') {
            return Err(unsupported_compat_arg("pip search", arg));
        } else {
            query.push(arg.clone());
        }
        index += 1;
    }
    Ok(PipCompatAction::Search { query })
}

fn pip_search_ignored_equals_flag(arg: &str) -> bool {
    [
        "--index=",
        "--log=",
        "--proxy=",
        "--retries=",
        "--timeout=",
        "--exists-action=",
        "--trusted-host=",
        "--cert=",
        "--client-cert=",
        "--cache-dir=",
        "--use-feature=",
        "--use-deprecated=",
    ]
    .iter()
    .any(|prefix| arg.starts_with(prefix))
}

fn parse_pip_config_args(args: &[String]) -> Result<PipCompatAction, OmcRegistryError> {
    let PipConfigArgs {
        editor,
        json,
        location,
        mut positionals,
    } = parse_pip_config_common_args(args)?;
    let command = if positionals.is_empty() {
        "list".to_owned()
    } else {
        positionals.remove(0)
    };
    match command.as_str() {
        "get" => {
            if positionals.is_empty() {
                return Err(OmcRegistryError::UnsupportedSpec(
                    "pip config get needs at least one key".to_owned(),
                ));
            }
            Ok(PipCompatAction::Config {
                action: PipConfigAction::Get {
                    keys: positionals,
                    json,
                },
            })
        }
        "list" => {
            if !positionals.is_empty() {
                return Err(unsupported_compat_arg("pip config list", &positionals[0]));
            }
            Ok(PipCompatAction::Config {
                action: PipConfigAction::List { json },
            })
        }
        "debug" => {
            if !positionals.is_empty() {
                return Err(unsupported_compat_arg("pip config debug", &positionals[0]));
            }
            Ok(PipCompatAction::Config {
                action: PipConfigAction::Debug,
            })
        }
        "edit" => {
            if !positionals.is_empty() {
                return Err(unsupported_compat_arg("pip config edit", &positionals[0]));
            }
            Ok(PipCompatAction::ConfigEdit { location, editor })
        }
        "set" => {
            let assignments = parse_pip_config_assignments(positionals)?;
            Ok(PipCompatAction::Config {
                action: PipConfigAction::Set {
                    assignments,
                    location,
                },
            })
        }
        "unset" | "delete" | "del" | "remove" | "rm" => {
            if positionals.is_empty() {
                return Err(OmcRegistryError::UnsupportedSpec(
                    "pip config unset needs at least one key".to_owned(),
                ));
            }
            Ok(PipCompatAction::Config {
                action: PipConfigAction::Unset {
                    keys: positionals,
                    location,
                },
            })
        }
        other => Err(OmcRegistryError::UnsupportedSpec(format!(
            "unsupported pip config command `{other}`"
        ))),
    }
}

#[derive(Debug)]
struct PipConfigArgs {
    editor: Option<String>,
    json: bool,
    location: PipConfigLocation,
    positionals: Vec<String>,
}

fn parse_pip_config_common_args(args: &[String]) -> Result<PipConfigArgs, OmcRegistryError> {
    let mut editor = None;
    let mut json = false;
    let mut location = PipConfigLocation::Auto;
    let mut positionals = Vec::new();
    let mut index = 0;
    while index < args.len() {
        let arg = &args[index];
        if arg == "--json" {
            json = true;
        } else if arg == "--user" {
            location = PipConfigLocation::User;
        } else if arg == "--site" {
            location = PipConfigLocation::Site;
        } else if arg == "--global" {
            location = PipConfigLocation::Global;
        } else if arg == "--isolated" || pip_ignored_verbosity_flag(arg) {
        } else if arg == "--editor" {
            index += 1;
            let Some(value) = args.get(index) else {
                return Err(OmcRegistryError::UnsupportedSpec(
                    "--editor needs a value".to_owned(),
                ));
            };
            editor = Some(value.clone());
        } else if arg.starts_with("--editor=") {
            editor = Some(arg["--editor=".len()..].to_owned());
        } else if arg.starts_with('-') {
            return Err(unsupported_compat_arg("pip config", arg));
        } else {
            positionals.push(arg.clone());
        }
        index += 1;
    }
    Ok(PipConfigArgs {
        editor,
        json,
        location,
        positionals,
    })
}

fn parse_pip_config_assignments(
    positionals: Vec<String>,
) -> Result<Vec<(String, String)>, OmcRegistryError> {
    if positionals.is_empty() {
        return Err(OmcRegistryError::UnsupportedSpec(
            "pip config set needs a key and value".to_owned(),
        ));
    }
    if positionals.iter().any(|value| value.contains('=')) {
        return positionals
            .into_iter()
            .map(|assignment| {
                let Some((key, value)) = assignment.split_once('=') else {
                    return Err(OmcRegistryError::UnsupportedSpec(format!(
                        "pip config set mixed assignment formats at `{assignment}`"
                    )));
                };
                pip_config_assignment(key, value)
            })
            .collect();
    }
    if positionals.len() != 2 {
        return Err(OmcRegistryError::UnsupportedSpec(
            "pip config set needs either KEY VALUE or KEY=VALUE".to_owned(),
        ));
    }
    pip_config_assignment(&positionals[0], &positionals[1]).map(|assignment| vec![assignment])
}

fn pip_config_assignment(key: &str, value: &str) -> Result<(String, String), OmcRegistryError> {
    let key = key.trim();
    if key.is_empty() {
        return Err(OmcRegistryError::UnsupportedSpec(
            "pip config key cannot be empty".to_owned(),
        ));
    }
    Ok((key.to_owned(), value.trim().to_owned()))
}

fn parse_pip_uninstall_args(args: &[String]) -> Result<PipCompatAction, OmcRegistryError> {
    let expanded_short_clusters = expand_pip_uninstall_short_clusters(args);
    let args = expanded_short_clusters.as_slice();
    let mut requirements = Vec::new();
    let mut user = false;
    let mut filtered = Vec::new();
    let mut index = 0;
    while index < args.len() {
        let arg = &args[index];
        if arg == "-r" || arg == "--requirement" {
            index += 1;
            let Some(path) = args.get(index) else {
                return Err(OmcRegistryError::UnsupportedSpec(format!(
                    "{arg} needs a path"
                )));
            };
            requirements.push(PathBuf::from(path));
        } else if let Some(path) = arg.strip_prefix("--requirement=") {
            requirements.push(PathBuf::from(path));
        } else if let Some(path) = pip_attached_short_value(arg, 'r') {
            requirements.push(PathBuf::from(path));
        } else if matches!(arg.as_str(), "--user" | "--user=true") {
            user = true;
        } else if arg == "--user=false" {
            user = false;
        } else if matches!(arg.as_str(), "-y" | "--yes" | "--break-system-packages")
            || pip_global_ignored_bool_flag(arg)
        {
        } else if pip_global_ignored_value_flag(arg) {
            index += 1;
            if args.get(index).is_none() {
                return Err(OmcRegistryError::UnsupportedSpec(format!(
                    "{arg} needs a value"
                )));
            }
        } else if pip_global_ignored_equals_flag(arg) {
        } else {
            filtered.push(arg.clone());
        }
        index += 1;
    }

    let CommonCompatFlags {
        allow,
        allow_flow,
        allow_all_host,
        positionals,
        ..
    } = parse_common_compat_flags(&filtered, false)?;
    if positionals.is_empty() && requirements.is_empty() {
        return Err(OmcRegistryError::UnsupportedSpec(
            "pip uninstall needs at least one package or requirement file".to_owned(),
        ));
    }
    Ok(PipCompatAction::Uninstall {
        specs: positionals,
        requirements,
        user,
        allow,
        allow_flow,
        allow_all_host,
    })
}

fn expand_pip_uninstall_short_clusters(args: &[String]) -> Vec<String> {
    args.iter()
        .flat_map(|arg| {
            expand_pip_short_cluster(arg, &['y'], &['r']).unwrap_or_else(|| vec![arg.clone()])
        })
        .collect()
}

fn parse_pip_show_args(args: &[String]) -> Result<PipCompatAction, OmcRegistryError> {
    let expanded_short_clusters = expand_pip_show_short_clusters(args);
    let args = expanded_short_clusters.as_slice();
    let mut specs = Vec::new();
    let mut files = false;
    let mut user = false;
    for arg in args {
        if arg == "--disable-pip-version-check" || pip_ignored_verbosity_flag(arg) {
            continue;
        }
        if matches!(arg.as_str(), "-f" | "--files") {
            files = true;
            continue;
        }
        if matches!(arg.as_str(), "--user" | "--user=true") {
            user = true;
            continue;
        }
        if arg == "--user=false" {
            user = false;
            continue;
        }
        if arg.starts_with('-') {
            return Err(unsupported_compat_arg("pip show", arg));
        }
        specs.push(arg.clone());
    }
    if specs.is_empty() {
        return Err(OmcRegistryError::UnsupportedSpec(
            "pip show needs at least one package".to_owned(),
        ));
    }
    Ok(PipCompatAction::Show { specs, files, user })
}

fn expand_pip_show_short_clusters(args: &[String]) -> Vec<String> {
    args.iter()
        .flat_map(|arg| {
            expand_pip_short_cluster(arg, &['f'], &[]).unwrap_or_else(|| vec![arg.clone()])
        })
        .collect()
}

fn parse_pip_hash_args(args: &[String]) -> Result<PipCompatAction, OmcRegistryError> {
    let mut algorithm = PipHashAlgorithm::Sha256;
    let mut paths = Vec::new();
    let mut index = 0;
    while index < args.len() {
        let arg = &args[index];
        if arg == "-a" || arg == "--algorithm" {
            index += 1;
            let Some(value) = args.get(index) else {
                return Err(OmcRegistryError::UnsupportedSpec(format!(
                    "{arg} needs a value"
                )));
            };
            algorithm = parse_pip_hash_algorithm(value)?;
        } else if let Some(value) = arg.strip_prefix("--algorithm=") {
            algorithm = parse_pip_hash_algorithm(value)?;
        } else if let Some(value) = pip_attached_short_value(arg, 'a') {
            algorithm = parse_pip_hash_algorithm(value)?;
        } else if arg == "--disable-pip-version-check" || pip_ignored_verbosity_flag(arg) {
        } else if arg.starts_with('-') {
            return Err(unsupported_compat_arg("pip hash", arg));
        } else {
            paths.push(PathBuf::from(arg));
        }
        index += 1;
    }
    if paths.is_empty() {
        return Err(OmcRegistryError::UnsupportedSpec(
            "pip hash needs at least one file".to_owned(),
        ));
    }
    Ok(PipCompatAction::Hash { algorithm, paths })
}

fn parse_pip_hash_algorithm(value: &str) -> Result<PipHashAlgorithm, OmcRegistryError> {
    match value.to_ascii_lowercase().as_str() {
        "sha256" => Ok(PipHashAlgorithm::Sha256),
        "sha384" => Ok(PipHashAlgorithm::Sha384),
        "sha512" => Ok(PipHashAlgorithm::Sha512),
        other => Err(OmcRegistryError::UnsupportedSpec(format!(
            "unsupported pip hash algorithm `{other}`"
        ))),
    }
}

fn parse_pip_cache_args(args: &[String]) -> Result<PipCompatAction, OmcRegistryError> {
    let mut filtered = Vec::new();
    let mut format = PipCacheListFormat::Human;
    let mut index = 0;
    while index < args.len() {
        let arg = &args[index];
        if arg == "--disable-pip-version-check" || pip_ignored_verbosity_flag(arg) {
        } else if arg == "--format" {
            index += 1;
            let Some(value) = args.get(index) else {
                return Err(OmcRegistryError::UnsupportedSpec(
                    "pip cache --format needs a value".to_owned(),
                ));
            };
            format = parse_pip_cache_list_format(value)?;
        } else if let Some(value) = arg.strip_prefix("--format=") {
            format = parse_pip_cache_list_format(value)?;
        } else if pip_global_ignored_bool_flag(arg) || pip_global_ignored_equals_flag(arg) {
        } else if pip_global_ignored_value_flag(arg) {
            index += 1;
            if args.get(index).is_none() {
                return Err(OmcRegistryError::UnsupportedSpec(format!(
                    "{arg} needs a value"
                )));
            }
        } else if arg.starts_with('-') {
            return Err(unsupported_compat_arg("pip cache", arg));
        } else {
            filtered.push(arg.clone());
        }
        index += 1;
    }
    let Some(command) = filtered.first().map(String::as_str) else {
        return Err(OmcRegistryError::UnsupportedSpec(
            "pip cache needs a command such as dir, list, remove, or purge".to_owned(),
        ));
    };
    let rest = &filtered[1..];
    let action = match command {
        "dir" => {
            if !rest.is_empty() {
                return Err(unsupported_compat_arg("pip cache dir", &rest[0]));
            }
            PipCacheAction::Dir
        }
        "info" => {
            if !rest.is_empty() {
                return Err(unsupported_compat_arg("pip cache info", &rest[0]));
            }
            PipCacheAction::Info
        }
        "list" => {
            if rest.len() > 1 {
                return Err(unsupported_compat_arg("pip cache list", &rest[1]));
            }
            PipCacheAction::List {
                pattern: rest.first().cloned(),
                format,
            }
        }
        "remove" | "rm" => {
            if rest.len() != 1 {
                return Err(OmcRegistryError::UnsupportedSpec(
                    "pip cache remove needs exactly one pattern".to_owned(),
                ));
            }
            PipCacheAction::Remove {
                pattern: rest[0].clone(),
            }
        }
        "purge" => {
            if !rest.is_empty() {
                return Err(unsupported_compat_arg("pip cache purge", &rest[0]));
            }
            PipCacheAction::Purge
        }
        other => {
            return Err(OmcRegistryError::UnsupportedSpec(format!(
                "unsupported pip cache command `{other}`"
            )))
        }
    };
    Ok(PipCompatAction::Cache { action })
}

fn parse_pip_cache_list_format(value: &str) -> Result<PipCacheListFormat, OmcRegistryError> {
    match value {
        "human" => Ok(PipCacheListFormat::Human),
        "abspath" => Ok(PipCacheListFormat::Abspath),
        other => Err(OmcRegistryError::UnsupportedSpec(format!(
            "unsupported pip cache list format `{other}`"
        ))),
    }
}

fn parse_pip_check_args(args: &[String]) -> Result<PipCompatAction, OmcRegistryError> {
    let mut user = false;
    for arg in args {
        if matches!(arg.as_str(), "--user" | "--user=true") {
            user = true;
            continue;
        }
        if arg == "--user=false" {
            user = false;
            continue;
        }
        if arg == "--disable-pip-version-check" || pip_ignored_verbosity_flag(arg) {
            continue;
        }
        return Err(unsupported_compat_arg("pip check", arg));
    }
    Ok(PipCompatAction::Check { user })
}

fn parse_pip_debug_args(args: &[String]) -> Result<PipCompatAction, OmcRegistryError> {
    let mut action = PipDebugAction {
        verbose: false,
        platform: None,
        python_version: None,
        implementation: None,
        abis: Vec::new(),
    };
    let mut index = 0;
    while index < args.len() {
        let arg = &args[index];
        if matches!(arg.as_str(), "--debug" | "--disable-pip-version-check")
            || pip_ignored_verbosity_flag(arg)
        {
            if pip_verbose_flag(arg) {
                action.verbose = true;
            }
        } else if arg == "--platform" {
            action.platform = Some(pip_debug_flag_value(args, &mut index, arg)?);
        } else if let Some(value) = arg.strip_prefix("--platform=") {
            action.platform = Some(value.to_owned());
        } else if arg == "--python-version" {
            action.python_version = Some(pip_debug_flag_value(args, &mut index, arg)?);
        } else if let Some(value) = arg.strip_prefix("--python-version=") {
            action.python_version = Some(value.to_owned());
        } else if arg == "--implementation" {
            action.implementation = Some(pip_debug_flag_value(args, &mut index, arg)?);
        } else if let Some(value) = arg.strip_prefix("--implementation=") {
            action.implementation = Some(value.to_owned());
        } else if arg == "--abi" {
            action
                .abis
                .push(pip_debug_flag_value(args, &mut index, arg)?);
        } else if let Some(value) = arg.strip_prefix("--abi=") {
            action.abis.push(value.to_owned());
        } else if matches!(
            arg.as_str(),
            "--cert" | "--client-cert" | "--cache-dir" | "--log" | "--proxy" | "--timeout"
        ) {
            index += 1;
            if args.get(index).is_none() {
                return Err(OmcRegistryError::UnsupportedSpec(format!(
                    "{arg} needs a value"
                )));
            }
        } else if pip_debug_ignored_equals_flag(arg) {
        } else {
            return Err(unsupported_compat_arg("pip debug", arg));
        }
        index += 1;
    }
    Ok(PipCompatAction::Debug { action })
}

fn pip_debug_flag_value(
    args: &[String],
    index: &mut usize,
    flag: &str,
) -> Result<String, OmcRegistryError> {
    *index += 1;
    args.get(*index)
        .cloned()
        .ok_or_else(|| OmcRegistryError::UnsupportedSpec(format!("{flag} needs a value")))
}

fn pip_debug_ignored_equals_flag(arg: &str) -> bool {
    [
        "--cert=",
        "--client-cert=",
        "--cache-dir=",
        "--log=",
        "--proxy=",
        "--timeout=",
    ]
    .iter()
    .any(|prefix| arg.starts_with(prefix))
}

fn parse_pip_inspect_args(args: &[String]) -> Result<PipCompatAction, OmcRegistryError> {
    let mut paths = Vec::new();
    let mut user = false;
    let mut index = 0;
    while index < args.len() {
        let arg = &args[index];
        if arg == "--user" {
            user = true;
        } else if matches!(arg.as_str(), "--local" | "--disable-pip-version-check")
            || pip_ignored_verbosity_flag(arg)
        {
        } else if arg == "--path" {
            index += 1;
            let Some(path) = args.get(index) else {
                return Err(OmcRegistryError::UnsupportedSpec(format!(
                    "{arg} needs a value"
                )));
            };
            paths.push(PathBuf::from(path));
        } else if let Some(path) = arg.strip_prefix("--path=") {
            paths.push(PathBuf::from(path));
        } else {
            return Err(unsupported_compat_arg("pip inspect", arg));
        }
        index += 1;
    }
    Ok(PipCompatAction::Inspect { paths, user })
}

fn parse_pip_freeze_args(args: &[String]) -> Result<PipFreezeAction, OmcRegistryError> {
    let expanded_short_clusters = expand_pip_freeze_short_clusters(args);
    let args = expanded_short_clusters.as_slice();
    let mut action = PipFreezeAction::default();
    let mut index = 0;
    while index < args.len() {
        let arg = &args[index];
        if arg == "--user" {
            action.user = true;
        } else if matches!(
            arg.as_str(),
            "--all" | "--local" | "-l" | "--exclude-editable" | "--disable-pip-version-check"
        ) || pip_ignored_verbosity_flag(arg)
        {
            if arg == "--exclude-editable" {
                action.exclude_editable = true;
            }
        } else if matches!(
            arg.as_str(),
            "-r" | "--requirement" | "--path" | "--exclude"
        ) {
            index += 1;
            let Some(value) = args.get(index) else {
                return Err(OmcRegistryError::UnsupportedSpec(format!(
                    "{arg} needs a value"
                )));
            };
            if arg == "--path" {
                action.paths.push(PathBuf::from(value));
            } else if arg == "--exclude" {
                action.exclude.push(value.clone());
            } else {
                action.requirements.push(PathBuf::from(value));
            }
        } else if let Some(path) = arg.strip_prefix("--path=") {
            action.paths.push(PathBuf::from(path));
        } else if let Some(exclude) = arg.strip_prefix("--exclude=") {
            action.exclude.push(exclude.to_owned());
        } else if let Some(requirement) = arg.strip_prefix("--requirement=") {
            action.requirements.push(PathBuf::from(requirement));
        } else if let Some(requirement) = pip_attached_short_value(arg, 'r') {
            action.requirements.push(PathBuf::from(requirement));
        } else {
            return Err(unsupported_compat_arg("pip freeze", arg));
        }
        index += 1;
    }
    Ok(action)
}

fn parse_pip_install_args(args: &[String]) -> Result<PipCompatAction, OmcRegistryError> {
    let expanded_short_clusters = expand_pip_install_short_clusters(args);
    let args = expanded_short_clusters.as_slice();
    let mut requirements = Vec::new();
    let mut constraints = Vec::new();
    let mut script_requirements = Vec::new();
    let mut report = None;
    let mut dry_run = false;
    let mut index_url = None;
    let mut extra_index_urls = Vec::new();
    let mut find_links = Vec::new();
    let mut no_index = false;
    let mut binary_all = None;
    let mut binary_packages = BTreeMap::new();
    let mut require_hashes = false;
    let mut no_deps = false;
    let mut allow_prereleases = false;
    let mut release_controls = PypiReleaseControls::default();
    let mut uploaded_prior_to = None;
    let mut upgrade = false;
    let mut force_reinstall = false;
    let mut compatibility = PipCompatibilityTarget::default();
    let mut target = None;
    let mut prefix = None;
    let mut root = None;
    let mut user = false;
    let mut groups = Vec::new();
    let mut archive_references = Vec::new();
    let mut local_paths = Vec::new();
    let mut local_directories = Vec::new();
    let mut vcs_requirements = Vec::new();
    let mut filtered = Vec::new();
    let mut index = 0;
    while index < args.len() {
        let arg = &args[index];
        if arg == "-r" || arg == "--requirement" {
            index += 1;
            let Some(path) = args.get(index) else {
                return Err(OmcRegistryError::UnsupportedSpec(format!(
                    "{arg} needs a path"
                )));
            };
            requirements.push(PathBuf::from(path));
        } else if let Some(path) = arg.strip_prefix("--requirement=") {
            requirements.push(PathBuf::from(path));
        } else if let Some(path) = pip_attached_short_value(arg, 'r') {
            requirements.push(PathBuf::from(path));
        } else if arg == "-c" || arg == "--constraint" {
            index += 1;
            let Some(path) = args.get(index) else {
                return Err(OmcRegistryError::UnsupportedSpec(format!(
                    "{arg} needs a path"
                )));
            };
            constraints.push(PathBuf::from(path));
        } else if let Some(path) = arg.strip_prefix("--constraint=") {
            constraints.push(PathBuf::from(path));
        } else if let Some(path) = pip_attached_short_value(arg, 'c') {
            constraints.push(PathBuf::from(path));
        } else if arg == "--requirements-from-script" {
            index += 1;
            let Some(path) = args.get(index) else {
                return Err(OmcRegistryError::UnsupportedSpec(format!(
                    "{arg} needs a path"
                )));
            };
            script_requirements.push(PathBuf::from(path));
        } else if let Some(path) = arg.strip_prefix("--requirements-from-script=") {
            script_requirements.push(PathBuf::from(path));
        } else if arg == "--report" {
            index += 1;
            let Some(path) = args.get(index) else {
                return Err(OmcRegistryError::UnsupportedSpec(format!(
                    "{arg} needs a path"
                )));
            };
            report = Some(PathBuf::from(path));
        } else if let Some(path) = arg.strip_prefix("--report=") {
            report = Some(PathBuf::from(path));
        } else if let Some(value) = pip_bool_flag_value(arg, "--dry-run") {
            dry_run = value;
        } else if arg == "-i" || arg == "--index-url" {
            index += 1;
            let Some(url) = args.get(index) else {
                return Err(OmcRegistryError::UnsupportedSpec(format!(
                    "{arg} needs a URL"
                )));
            };
            index_url = Some(url.clone());
        } else if let Some(url) = arg.strip_prefix("--index-url=") {
            index_url = Some(url.to_owned());
        } else if let Some(url) = pip_attached_short_value(arg, 'i') {
            index_url = Some(url.to_owned());
        } else if arg == "--extra-index-url" {
            index += 1;
            let Some(url) = args.get(index) else {
                return Err(OmcRegistryError::UnsupportedSpec(format!(
                    "{arg} needs a URL"
                )));
            };
            extra_index_urls.push(url.clone());
        } else if let Some(url) = arg.strip_prefix("--extra-index-url=") {
            extra_index_urls.push(url.to_owned());
        } else if arg == "-f" || arg == "--find-links" {
            index += 1;
            let Some(value) = args.get(index) else {
                return Err(OmcRegistryError::UnsupportedSpec(format!(
                    "{arg} needs a path or URL"
                )));
            };
            find_links.push(value.clone());
        } else if let Some(value) = arg.strip_prefix("--find-links=") {
            find_links.push(value.to_owned());
        } else if let Some(value) = pip_attached_short_value(arg, 'f') {
            find_links.push(value.to_owned());
        } else if let Some(value) = pip_bool_flag_value(arg, "--no-index") {
            no_index = value;
        } else if let Some(value) = pip_bool_flag_value(arg, "--require-hashes") {
            require_hashes = value;
        } else if let Some(value) = pip_bool_flag_value(arg, "--no-deps") {
            no_deps = value;
        } else if let Some(value) = pip_bool_flag_value(arg, "--pre") {
            allow_prereleases = value;
        } else if arg == "--all-releases" {
            let value = pip_target_flag_value(args, &mut index, arg)?;
            apply_pypi_release_control(&mut release_controls.all_releases, &value);
        } else if let Some(value) = arg.strip_prefix("--all-releases=") {
            apply_pypi_release_control(&mut release_controls.all_releases, value);
        } else if arg == "--only-final" {
            let value = pip_target_flag_value(args, &mut index, arg)?;
            apply_pypi_release_control(&mut release_controls.only_final, &value);
        } else if let Some(value) = arg.strip_prefix("--only-final=") {
            apply_pypi_release_control(&mut release_controls.only_final, value);
        } else if arg == "--uploaded-prior-to" {
            uploaded_prior_to = Some(pip_target_flag_value(args, &mut index, arg)?);
        } else if let Some(value) = arg.strip_prefix("--uploaded-prior-to=") {
            uploaded_prior_to = Some(value.to_owned());
        } else if arg == "--platform" {
            compatibility
                .platforms
                .push(pip_target_flag_value(args, &mut index, arg)?);
        } else if let Some(value) = arg.strip_prefix("--platform=") {
            compatibility.platforms.push(value.to_owned());
        } else if arg == "--python-version" {
            compatibility.python_version = Some(pip_target_flag_value(args, &mut index, arg)?);
        } else if let Some(value) = arg.strip_prefix("--python-version=") {
            compatibility.python_version = Some(value.to_owned());
        } else if arg == "--implementation" {
            compatibility.implementation = Some(pip_target_flag_value(args, &mut index, arg)?);
        } else if let Some(value) = arg.strip_prefix("--implementation=") {
            compatibility.implementation = Some(value.to_owned());
        } else if arg == "--abi" {
            compatibility
                .abis
                .push(pip_target_flag_value(args, &mut index, arg)?);
        } else if let Some(value) = arg.strip_prefix("--abi=") {
            compatibility.abis.push(value.to_owned());
        } else if arg == "-t" || arg == "--target" {
            index += 1;
            let Some(path) = args.get(index) else {
                return Err(OmcRegistryError::UnsupportedSpec(format!(
                    "{arg} needs a path"
                )));
            };
            target = Some(PathBuf::from(path));
        } else if let Some(path) = arg.strip_prefix("--target=") {
            target = Some(PathBuf::from(path));
        } else if let Some(path) = pip_attached_short_value(arg, 't') {
            target = Some(PathBuf::from(path));
        } else if arg == "--prefix" {
            index += 1;
            let Some(path) = args.get(index) else {
                return Err(OmcRegistryError::UnsupportedSpec(format!(
                    "{arg} needs a path"
                )));
            };
            prefix = Some(PathBuf::from(path));
        } else if let Some(path) = arg.strip_prefix("--prefix=") {
            prefix = Some(PathBuf::from(path));
        } else if arg == "--root" {
            index += 1;
            let Some(path) = args.get(index) else {
                return Err(OmcRegistryError::UnsupportedSpec(format!(
                    "{arg} needs a path"
                )));
            };
            root = Some(PathBuf::from(path));
        } else if let Some(path) = arg.strip_prefix("--root=") {
            root = Some(PathBuf::from(path));
        } else if matches!(arg.as_str(), "--user" | "--user=true") {
            user = true;
        } else if arg == "--user=false" {
            user = false;
        } else if arg == "--group" {
            index += 1;
            let Some(group) = args.get(index) else {
                return Err(OmcRegistryError::UnsupportedSpec(format!(
                    "{arg} needs a group"
                )));
            };
            match pip_project_group_arg(group)? {
                PipProjectGroupArg::Current(group) => groups.push(group),
                PipProjectGroupArg::Local(requirement) => local_paths.push(requirement),
            }
        } else if let Some(group) = arg.strip_prefix("--group=") {
            match pip_project_group_arg(group)? {
                PipProjectGroupArg::Current(group) => groups.push(group),
                PipProjectGroupArg::Local(requirement) => local_paths.push(requirement),
            }
        } else if arg == "--prefer-binary" {
        } else if arg == "--only-binary" || arg == "--no-binary" {
            index += 1;
            let Some(value) = args.get(index) else {
                return Err(OmcRegistryError::UnsupportedSpec(format!(
                    "{arg} needs a value"
                )));
            };
            let mode = if arg == "--only-binary" {
                PypiBinaryMode::Binary
            } else {
                PypiBinaryMode::Source
            };
            apply_pypi_binary_option(&mut binary_all, &mut binary_packages, mode, value);
        } else if let Some(value) = arg.strip_prefix("--only-binary=") {
            apply_pypi_binary_option(
                &mut binary_all,
                &mut binary_packages,
                PypiBinaryMode::Binary,
                value,
            );
        } else if let Some(value) = arg.strip_prefix("--no-binary=") {
            apply_pypi_binary_option(
                &mut binary_all,
                &mut binary_packages,
                PypiBinaryMode::Source,
                value,
            );
        } else if arg == "--trusted-host" {
            index += 1;
            if args.get(index).is_none() {
                return Err(OmcRegistryError::UnsupportedSpec(format!(
                    "{arg} needs a value"
                )));
            }
        } else if arg.starts_with("--trusted-host=") {
        } else if arg == "-e" || arg == "--editable" {
            index += 1;
            let Some(path) = args.get(index) else {
                return Err(OmcRegistryError::UnsupportedSpec(format!(
                    "{arg} needs a path"
                )));
            };
            if let Some(requirement) = parse_pypi_vcs_requirement(path)? {
                vcs_requirements.push(requirement);
            } else {
                local_paths.push(pip_local_path_arg(path)?);
            }
        } else if let Some(path) = arg.strip_prefix("--editable=") {
            if let Some(requirement) = parse_pypi_vcs_requirement(path)? {
                vcs_requirements.push(requirement);
            } else {
                local_paths.push(pip_local_path_arg(path)?);
            }
        } else if let Some(path) = pip_attached_short_value(arg, 'e') {
            if let Some(requirement) = parse_pypi_vcs_requirement(path)? {
                vcs_requirements.push(requirement);
            } else {
                local_paths.push(pip_local_path_arg(path)?);
            }
        } else if matches!(arg.as_str(), "--upgrade" | "-U") {
            upgrade = true;
        } else if arg == "--upgrade=false" {
            upgrade = false;
        } else if matches!(
            arg.as_str(),
            "--force-reinstall" | "--ignore-installed" | "-I"
        ) {
            force_reinstall = true;
        } else if matches!(
            arg.as_str(),
            "--break-system-packages"
                | "--disable-pip-version-check"
                | "--no-cache-dir"
                | "--isolated"
                | "--require-virtualenv"
                | "--ignore-requires-python"
                | "--no-build-isolation"
                | "--check-build-dependencies"
                | "--use-pep517"
                | "--no-use-pep517"
                | "--compile"
                | "--no-compile"
                | "--no-color"
                | "--no-input"
                | "--no-python-version-warning"
                | "--no-warn-script-location"
                | "--no-warn-conflicts"
                | "--no-clean"
        ) || pip_ignored_verbosity_flag(arg)
        {
        } else if pip_ignored_install_value_flag(arg) {
            index += 1;
            if args.get(index).is_none() {
                return Err(OmcRegistryError::UnsupportedSpec(format!(
                    "{arg} needs a value"
                )));
            }
        } else if pip_ignored_install_equals_flag(arg) {
        } else if is_pip_archive_arg(arg) {
            archive_references.push(arg.clone());
        } else if let Some(requirement) = parse_pypi_vcs_requirement(arg)? {
            vcs_requirements.push(requirement);
        } else if is_pip_pylock_requirements_arg(arg) {
            requirements.push(PathBuf::from(arg));
        } else if is_pip_local_directory_arg(arg) {
            local_directories.push(pip_local_path_arg(arg)?);
        } else {
            filtered.push(arg.clone());
        }
        index += 1;
    }

    let CommonCompatFlags {
        allow,
        allow_flow,
        allow_all_host,
        positionals,
        ..
    } = parse_common_compat_flags(&filtered, false)?;

    Ok(PipCompatAction::Install(Box::new(PipInstallAction {
        specs: positionals.into_iter().filter(|spec| spec != ".").collect(),
        requirements,
        constraints,
        script_requirements,
        groups,
        report,
        dry_run,
        archive_references,
        local_paths,
        local_directories,
        index_url,
        extra_index_urls,
        find_links,
        no_index,
        binary_all,
        binary_packages,
        require_hashes,
        no_deps,
        allow_prereleases,
        release_controls,
        uploaded_prior_to,
        upgrade,
        force_reinstall,
        compatibility,
        target,
        prefix,
        root,
        user,
        vcs_requirements,
        allow,
        allow_flow,
        allow_all_host,
    })))
}

fn parse_pip_lock_args(args: &[String]) -> Result<PipCompatAction, OmcRegistryError> {
    let mut output = PathBuf::from("pylock.toml");
    let mut install_args = Vec::new();
    let mut index = 0;
    while index < args.len() {
        let arg = &args[index];
        if arg == "-o" || arg == "--output" {
            index += 1;
            let Some(path) = args.get(index) else {
                return Err(OmcRegistryError::UnsupportedSpec(format!(
                    "{arg} needs a path"
                )));
            };
            output = PathBuf::from(path);
        } else if let Some(path) = arg.strip_prefix("--output=") {
            output = PathBuf::from(path);
        } else if arg == "--build-constraint" {
            index += 1;
            if args.get(index).is_none() {
                return Err(OmcRegistryError::UnsupportedSpec(format!(
                    "{arg} needs a path"
                )));
            }
        } else if arg.starts_with("--build-constraint=") {
        } else {
            install_args.push(arg.clone());
        }
        index += 1;
    }

    let PipCompatAction::Install(action) = parse_pip_install_args(&install_args)? else {
        unreachable!("parse_pip_install_args returns install actions")
    };
    Ok(PipCompatAction::Lock(Box::new(PipLockAction {
        install: *action,
        output,
    })))
}

fn expand_pip_install_short_clusters(args: &[String]) -> Vec<String> {
    args.iter()
        .flat_map(|arg| {
            expand_pip_short_cluster(arg, &['U', 'I'], &['r', 'c', 'i', 'f', 't', 'e', 'C'])
                .unwrap_or_else(|| vec![arg.clone()])
        })
        .collect()
}

fn expand_pip_freeze_short_clusters(args: &[String]) -> Vec<String> {
    args.iter()
        .flat_map(|arg| {
            expand_pip_short_cluster(arg, &['l'], &['r']).unwrap_or_else(|| vec![arg.clone()])
        })
        .collect()
}

fn parse_pip_download_args(args: &[String]) -> Result<PipCompatAction, OmcRegistryError> {
    parse_pip_artifact_args(args, PipArtifactCommand::Download)
}

fn parse_pip_wheel_args(args: &[String]) -> Result<PipCompatAction, OmcRegistryError> {
    parse_pip_artifact_args(args, PipArtifactCommand::Wheel)
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum PipArtifactCommand {
    Download,
    Wheel,
}

fn parse_pip_artifact_args(
    args: &[String],
    command: PipArtifactCommand,
) -> Result<PipCompatAction, OmcRegistryError> {
    let expanded_short_clusters = expand_pip_artifact_short_clusters(args, command);
    let args = expanded_short_clusters.as_slice();
    let mut requirements = Vec::new();
    let mut constraints = Vec::new();
    let mut index_url = None;
    let mut extra_index_urls = Vec::new();
    let mut find_links = Vec::new();
    let mut no_index = false;
    let mut binary_all = None;
    let mut binary_packages = BTreeMap::new();
    let mut require_hashes = false;
    let mut no_deps = false;
    let mut allow_prereleases = false;
    let mut release_controls = PypiReleaseControls::default();
    let mut uploaded_prior_to = None;
    let mut compatibility = PipCompatibilityTarget::default();
    let mut destination = PathBuf::from(".");
    let mut archive_references = Vec::new();
    let mut local_paths = Vec::new();
    let mut filtered = Vec::new();
    let mut index = 0;
    while index < args.len() {
        let arg = &args[index];
        if arg == "-r" || arg == "--requirement" {
            index += 1;
            let Some(path) = args.get(index) else {
                return Err(OmcRegistryError::UnsupportedSpec(format!(
                    "{arg} needs a path"
                )));
            };
            requirements.push(PathBuf::from(path));
        } else if let Some(path) = arg.strip_prefix("--requirement=") {
            requirements.push(PathBuf::from(path));
        } else if let Some(path) = pip_attached_short_value(arg, 'r') {
            requirements.push(PathBuf::from(path));
        } else if arg == "-c" || arg == "--constraint" {
            index += 1;
            let Some(path) = args.get(index) else {
                return Err(OmcRegistryError::UnsupportedSpec(format!(
                    "{arg} needs a path"
                )));
            };
            constraints.push(PathBuf::from(path));
        } else if let Some(path) = arg.strip_prefix("--constraint=") {
            constraints.push(PathBuf::from(path));
        } else if let Some(path) = pip_attached_short_value(arg, 'c') {
            constraints.push(PathBuf::from(path));
        } else if command == PipArtifactCommand::Download
            && (arg == "-d" || arg == "--dest" || arg == "--destination-dir")
        {
            index += 1;
            let Some(path) = args.get(index) else {
                return Err(OmcRegistryError::UnsupportedSpec(format!(
                    "{arg} needs a path"
                )));
            };
            destination = PathBuf::from(path);
        } else if command == PipArtifactCommand::Download
            && arg
                .strip_prefix("--dest=")
                .or_else(|| arg.strip_prefix("--destination-dir="))
                .is_some()
        {
            let path = arg
                .strip_prefix("--dest=")
                .or_else(|| arg.strip_prefix("--destination-dir="))
                .expect("checked path option");
            destination = PathBuf::from(path);
        } else if command == PipArtifactCommand::Download
            && pip_attached_short_value(arg, 'd').is_some()
        {
            let path = pip_attached_short_value(arg, 'd').expect("checked download dest");
            destination = PathBuf::from(path);
        } else if command == PipArtifactCommand::Wheel && (arg == "-w" || arg == "--wheel-dir") {
            index += 1;
            let Some(path) = args.get(index) else {
                return Err(OmcRegistryError::UnsupportedSpec(format!(
                    "{arg} needs a path"
                )));
            };
            destination = PathBuf::from(path);
        } else if command == PipArtifactCommand::Wheel && arg.starts_with("--wheel-dir=") {
            let path = arg
                .strip_prefix("--wheel-dir=")
                .expect("checked wheel-dir option");
            destination = PathBuf::from(path);
        } else if command == PipArtifactCommand::Wheel
            && pip_attached_short_value(arg, 'w').is_some()
        {
            let path = pip_attached_short_value(arg, 'w').expect("checked wheel dir");
            destination = PathBuf::from(path);
        } else if arg == "-i" || arg == "--index-url" {
            index += 1;
            let Some(url) = args.get(index) else {
                return Err(OmcRegistryError::UnsupportedSpec(format!(
                    "{arg} needs a URL"
                )));
            };
            index_url = Some(url.clone());
        } else if let Some(url) = arg.strip_prefix("--index-url=") {
            index_url = Some(url.to_owned());
        } else if let Some(url) = pip_attached_short_value(arg, 'i') {
            index_url = Some(url.to_owned());
        } else if arg == "--extra-index-url" {
            index += 1;
            let Some(url) = args.get(index) else {
                return Err(OmcRegistryError::UnsupportedSpec(format!(
                    "{arg} needs a URL"
                )));
            };
            extra_index_urls.push(url.clone());
        } else if let Some(url) = arg.strip_prefix("--extra-index-url=") {
            extra_index_urls.push(url.to_owned());
        } else if arg == "-f" || arg == "--find-links" {
            index += 1;
            let Some(value) = args.get(index) else {
                return Err(OmcRegistryError::UnsupportedSpec(format!(
                    "{arg} needs a path or URL"
                )));
            };
            find_links.push(value.clone());
        } else if let Some(value) = arg.strip_prefix("--find-links=") {
            find_links.push(value.to_owned());
        } else if let Some(value) = pip_attached_short_value(arg, 'f') {
            find_links.push(value.to_owned());
        } else if let Some(value) = pip_bool_flag_value(arg, "--no-index") {
            no_index = value;
        } else if let Some(value) = pip_bool_flag_value(arg, "--require-hashes") {
            require_hashes = value;
        } else if let Some(value) = pip_bool_flag_value(arg, "--no-deps") {
            no_deps = value;
        } else if let Some(value) = pip_bool_flag_value(arg, "--pre") {
            allow_prereleases = value;
        } else if arg == "--all-releases" {
            let value = pip_target_flag_value(args, &mut index, arg)?;
            apply_pypi_release_control(&mut release_controls.all_releases, &value);
        } else if let Some(value) = arg.strip_prefix("--all-releases=") {
            apply_pypi_release_control(&mut release_controls.all_releases, value);
        } else if arg == "--only-final" {
            let value = pip_target_flag_value(args, &mut index, arg)?;
            apply_pypi_release_control(&mut release_controls.only_final, &value);
        } else if let Some(value) = arg.strip_prefix("--only-final=") {
            apply_pypi_release_control(&mut release_controls.only_final, value);
        } else if arg == "--uploaded-prior-to" {
            uploaded_prior_to = Some(pip_target_flag_value(args, &mut index, arg)?);
        } else if let Some(value) = arg.strip_prefix("--uploaded-prior-to=") {
            uploaded_prior_to = Some(value.to_owned());
        } else if arg == "--platform" {
            compatibility
                .platforms
                .push(pip_target_flag_value(args, &mut index, arg)?);
        } else if let Some(value) = arg.strip_prefix("--platform=") {
            compatibility.platforms.push(value.to_owned());
        } else if arg == "--python-version" {
            compatibility.python_version = Some(pip_target_flag_value(args, &mut index, arg)?);
        } else if let Some(value) = arg.strip_prefix("--python-version=") {
            compatibility.python_version = Some(value.to_owned());
        } else if arg == "--implementation" {
            compatibility.implementation = Some(pip_target_flag_value(args, &mut index, arg)?);
        } else if let Some(value) = arg.strip_prefix("--implementation=") {
            compatibility.implementation = Some(value.to_owned());
        } else if arg == "--abi" {
            compatibility
                .abis
                .push(pip_target_flag_value(args, &mut index, arg)?);
        } else if let Some(value) = arg.strip_prefix("--abi=") {
            compatibility.abis.push(value.to_owned());
        } else if arg == "--prefer-binary" {
        } else if arg == "--only-binary" || arg == "--no-binary" {
            index += 1;
            let Some(value) = args.get(index) else {
                return Err(OmcRegistryError::UnsupportedSpec(format!(
                    "{arg} needs a value"
                )));
            };
            let mode = if arg == "--only-binary" {
                PypiBinaryMode::Binary
            } else {
                PypiBinaryMode::Source
            };
            apply_pypi_binary_option(&mut binary_all, &mut binary_packages, mode, value);
        } else if let Some(value) = arg.strip_prefix("--only-binary=") {
            apply_pypi_binary_option(
                &mut binary_all,
                &mut binary_packages,
                PypiBinaryMode::Binary,
                value,
            );
        } else if let Some(value) = arg.strip_prefix("--no-binary=") {
            apply_pypi_binary_option(
                &mut binary_all,
                &mut binary_packages,
                PypiBinaryMode::Source,
                value,
            );
        } else if arg == "--trusted-host" {
            index += 1;
            if args.get(index).is_none() {
                return Err(OmcRegistryError::UnsupportedSpec(format!(
                    "{arg} needs a value"
                )));
            }
        } else if (command == PipArtifactCommand::Wheel && arg == "--no-verify")
            || matches!(
                arg.as_str(),
                "--ignore-requires-python"
                    | "--no-build-isolation"
                    | "--check-build-dependencies"
                    | "--use-pep517"
                    | "--no-use-pep517"
                    | "--no-clean"
            )
            || pip_global_ignored_bool_flag(arg)
            || arg.starts_with("--trusted-host=")
        {
        } else if command == PipArtifactCommand::Wheel && (arg == "-e" || arg == "--editable") {
            index += 1;
            let Some(path) = args.get(index) else {
                return Err(OmcRegistryError::UnsupportedSpec(format!(
                    "{arg} needs a path"
                )));
            };
            local_paths.push(pip_local_path_arg(path)?);
        } else if command == PipArtifactCommand::Wheel && arg.starts_with("--editable=") {
            let path = arg
                .strip_prefix("--editable=")
                .expect("checked editable option");
            local_paths.push(pip_local_path_arg(path)?);
        } else if command == PipArtifactCommand::Wheel
            && pip_attached_short_value(arg, 'e').is_some()
        {
            let path = pip_attached_short_value(arg, 'e').expect("checked editable option");
            local_paths.push(pip_local_path_arg(path)?);
        } else if command == PipArtifactCommand::Wheel && pip_ignored_wheel_value_flag(arg) {
            index += 1;
            if args.get(index).is_none() {
                return Err(OmcRegistryError::UnsupportedSpec(format!(
                    "{arg} needs a value"
                )));
            }
        } else if command == PipArtifactCommand::Wheel && pip_ignored_wheel_equals_flag(arg) {
        } else if pip_ignored_download_value_flag(arg) {
            index += 1;
            if args.get(index).is_none() {
                return Err(OmcRegistryError::UnsupportedSpec(format!(
                    "{arg} needs a value"
                )));
            }
        } else if pip_ignored_download_equals_flag(arg) {
        } else if is_pip_archive_arg(arg) {
            archive_references.push(arg.clone());
        } else if is_pip_pylock_requirements_arg(arg) {
            requirements.push(PathBuf::from(arg));
        } else if is_pip_local_directory_arg(arg) {
            local_paths.push(pip_local_path_arg(arg)?);
        } else {
            filtered.push(arg.clone());
        }
        index += 1;
    }

    let CommonCompatFlags {
        allow,
        allow_flow,
        allow_all_host,
        positionals,
        ..
    } = parse_common_compat_flags(&filtered, false)?;

    let action = PipDownloadAction {
        specs: positionals.into_iter().filter(|spec| spec != ".").collect(),
        requirements,
        constraints,
        archive_references,
        local_paths,
        index_url,
        extra_index_urls,
        find_links,
        no_index,
        binary_all,
        binary_packages,
        require_hashes,
        no_deps,
        allow_prereleases,
        release_controls,
        uploaded_prior_to,
        compatibility,
        destination,
        allow,
        allow_flow,
        allow_all_host,
    };
    Ok(match command {
        PipArtifactCommand::Download => PipCompatAction::Download(Box::new(action)),
        PipArtifactCommand::Wheel => PipCompatAction::Wheel(Box::new(action)),
    })
}

fn expand_pip_artifact_short_clusters(args: &[String], command: PipArtifactCommand) -> Vec<String> {
    let value_flags = match command {
        PipArtifactCommand::Download => &['r', 'c', 'd', 'i', 'f'][..],
        PipArtifactCommand::Wheel => &['r', 'c', 'w', 'i', 'f', 'e', 'C'][..],
    };
    args.iter()
        .flat_map(|arg| {
            expand_pip_short_cluster(arg, &[], value_flags).unwrap_or_else(|| vec![arg.clone()])
        })
        .collect()
}

fn pip_ignored_install_value_flag(arg: &str) -> bool {
    matches!(
        arg,
        "--progress-bar"
            | "--build-constraint"
            | "--upgrade-strategy"
            | "--src"
            | "-C"
            | "--config-settings"
            | "--global-option"
            | "--install-option"
            | "--root-user-action"
            | "--log"
            | "--proxy"
            | "--retries"
            | "--timeout"
            | "--exists-action"
            | "--keyring-provider"
            | "--cert"
            | "--client-cert"
            | "--cache-dir"
            | "--use-feature"
            | "--use-deprecated"
    )
}

fn pip_ignored_install_equals_flag(arg: &str) -> bool {
    [
        "--progress-bar=",
        "--build-constraint=",
        "--upgrade-strategy=",
        "--src=",
        "-C=",
        "--config-settings=",
        "--global-option=",
        "--install-option=",
        "--root-user-action=",
        "--log=",
        "--proxy=",
        "--retries=",
        "--timeout=",
        "--exists-action=",
        "--keyring-provider=",
        "--cert=",
        "--client-cert=",
        "--cache-dir=",
        "--use-feature=",
        "--use-deprecated=",
    ]
    .iter()
    .any(|prefix| arg.starts_with(prefix))
}

fn pip_bool_flag_value(arg: &str, flag: &str) -> Option<bool> {
    if arg == flag {
        return Some(true);
    }
    let value = arg.strip_prefix(flag)?.strip_prefix('=')?;
    match value {
        "true" => Some(true),
        "false" => Some(false),
        _ => None,
    }
}

fn pip_attached_short_value(arg: &str, flag: char) -> Option<&str> {
    if arg.starts_with("--") {
        return None;
    }
    let rest = arg.strip_prefix('-')?;
    let value = rest.strip_prefix(flag)?;
    (!value.is_empty()).then_some(value)
}

fn expand_pip_short_cluster(
    arg: &str,
    bool_flags: &[char],
    value_flags: &[char],
) -> Option<Vec<String>> {
    if arg.starts_with("--") {
        return None;
    }
    let body = arg.strip_prefix('-')?;
    if body.chars().count() <= 1 {
        return None;
    }

    let chars = body.chars().collect::<Vec<_>>();
    if value_flags.contains(&chars[0]) {
        return (chars[0] == 'C' && chars.len() > 1)
            .then(|| vec!["-C".to_owned(), chars[1..].iter().collect::<String>()]);
    }

    let mut expanded = Vec::new();
    let mut index = 0;
    while index < chars.len() {
        let flag = chars[index];
        if matches!(flag, 'q' | 'v') || bool_flags.contains(&flag) {
            expanded.push(format!("-{flag}"));
            index += 1;
        } else if value_flags.contains(&flag) {
            let value = chars[index + 1..].iter().collect::<String>();
            if value.is_empty() {
                expanded.push(format!("-{flag}"));
            } else if flag == 'C' {
                expanded.push("-C".to_owned());
                expanded.push(value);
            } else {
                expanded.push(format!("-{flag}{value}"));
            }
            return Some(expanded);
        } else {
            return None;
        }
    }
    Some(expanded)
}

fn pip_target_flag_value(
    args: &[String],
    index: &mut usize,
    flag: &str,
) -> Result<String, OmcRegistryError> {
    *index += 1;
    args.get(*index)
        .cloned()
        .ok_or_else(|| OmcRegistryError::UnsupportedSpec(format!("{flag} needs a value")))
}

enum PipProjectGroupArg {
    Current(String),
    Local(PythonLocalRequirement),
}

fn pip_project_group_arg(value: &str) -> Result<PipProjectGroupArg, OmcRegistryError> {
    let value = value.trim();
    if value.is_empty() {
        return Err(OmcRegistryError::UnsupportedSpec(
            "pip install --group needs a non-empty group".to_owned(),
        ));
    }
    if let Some((path, group)) = value.rsplit_once(':') {
        let path = path.trim();
        let group = normalize_extra(group);
        if group.is_empty() {
            return Err(OmcRegistryError::UnsupportedSpec(
                "pip install --group needs a non-empty group".to_owned(),
            ));
        }
        if matches!(path, "" | "pyproject.toml" | "./pyproject.toml") {
            return Ok(PipProjectGroupArg::Current(group));
        }
        return Ok(PipProjectGroupArg::Local(PythonLocalRequirement::new(
            pip_project_group_path(path)?,
            BTreeSet::from([group]),
        )));
    }
    Ok(PipProjectGroupArg::Current(normalize_extra(value)))
}

fn pip_project_group_path(path: &str) -> Result<PathBuf, OmcRegistryError> {
    if path.trim().is_empty() {
        return Err(OmcRegistryError::UnsupportedSpec(
            "pip install --group needs a non-empty pyproject path".to_owned(),
        ));
    }
    let path = PathBuf::from(path);
    if path.file_name().and_then(|name| name.to_str()) == Some("pyproject.toml") {
        return Ok(path
            .parent()
            .filter(|parent| !parent.as_os_str().is_empty())
            .map(Path::to_path_buf)
            .unwrap_or_else(|| PathBuf::from(".")));
    }
    Ok(path)
}

fn pip_ignored_wheel_value_flag(arg: &str) -> bool {
    matches!(
        arg,
        "-C" | "--config-settings" | "--build-option" | "--global-option"
    )
}

fn pip_ignored_wheel_equals_flag(arg: &str) -> bool {
    [
        "-C=",
        "--config-settings=",
        "--build-option=",
        "--global-option=",
    ]
    .iter()
    .any(|prefix| arg.starts_with(prefix))
}

fn pip_ignored_download_value_flag(arg: &str) -> bool {
    matches!(
        arg,
        "--progress-bar"
            | "--build-constraint"
            | "--retries"
            | "--timeout"
            | "--exists-action"
            | "--keyring-provider"
            | "--cert"
            | "--client-cert"
            | "--proxy"
            | "--cache-dir"
            | "--log"
            | "--use-feature"
            | "--use-deprecated"
    )
}

fn pip_ignored_download_equals_flag(arg: &str) -> bool {
    [
        "--progress-bar=",
        "--build-constraint=",
        "--retries=",
        "--timeout=",
        "--exists-action=",
        "--keyring-provider=",
        "--cert=",
        "--client-cert=",
        "--proxy=",
        "--cache-dir=",
        "--log=",
        "--use-feature=",
        "--use-deprecated=",
    ]
    .iter()
    .any(|prefix| arg.starts_with(prefix))
}

fn npm_local_path_arg(value: &str) -> Result<PathBuf, OmcRegistryError> {
    let path = value
        .strip_prefix("file:")
        .or_else(|| value.strip_prefix("link:"))
        .unwrap_or(value);
    if path.starts_with("//") {
        let url = reqwest::Url::parse(value)
            .map_err(|_| OmcRegistryError::UnsupportedSpec(value.to_owned()))?;
        return url.to_file_path().map_err(|_| {
            OmcRegistryError::UnsupportedSpec(format!(
                "local npm dependency `{value}` must use a valid file URL"
            ))
        });
    }
    if path.trim().is_empty() {
        return Err(OmcRegistryError::UnsupportedSpec(
            "local npm path cannot be empty".to_owned(),
        ));
    }
    Ok(PathBuf::from(path))
}

fn is_npm_local_directory_arg(value: &str) -> bool {
    if is_npm_archive_arg(value) {
        return false;
    }
    let value = value
        .strip_prefix("file:")
        .or_else(|| value.strip_prefix("link:"))
        .unwrap_or(value);
    value == "."
        || value.starts_with("./")
        || value.starts_with("../")
        || value.starts_with('/')
        || value.starts_with("~/")
        || value.contains('\\')
}

fn is_npm_archive_arg(value: &str) -> bool {
    let path = value.strip_prefix("file:").unwrap_or(value);
    let path = path.split_once('#').map(|(path, _)| path).unwrap_or(path);
    let path = path.split_once('?').map(|(path, _)| path).unwrap_or(path);
    let lower = path.to_ascii_lowercase();
    (lower.ends_with(".tgz") || lower.ends_with(".tar.gz"))
        && (path.starts_with("https://")
            || path.starts_with("http://")
            || path.starts_with("./")
            || path.starts_with("../")
            || path.starts_with('/')
            || path.starts_with("~/")
            || path.contains('\\'))
}

fn pip_local_path_arg(value: &str) -> Result<PythonLocalRequirement, OmcRegistryError> {
    if value.starts_with("git+") || is_pip_archive_arg(value) {
        return Err(OmcRegistryError::UnsupportedSpec(format!(
            "pip editable path `{value}` must be a local directory"
        )));
    }
    let (path, extras) = pip_local_path_and_extras(value);
    let path = if let Some(path) = pip_local_file_url_path(path)? {
        return Ok(PythonLocalRequirement::new(path, extras));
    } else {
        path
    };
    let path = path
        .strip_prefix("file:")
        .or_else(|| path.strip_prefix("link:"))
        .unwrap_or(path);
    if path.trim().is_empty() {
        return Err(OmcRegistryError::UnsupportedSpec(
            "pip editable path cannot be empty".to_owned(),
        ));
    }
    Ok(PythonLocalRequirement::new(PathBuf::from(path), extras))
}

fn is_pip_local_directory_arg(value: &str) -> bool {
    if value.starts_with("git+") || is_pip_archive_arg(value) {
        return false;
    }
    let (path, _) = pip_local_path_and_extras(value);
    if path.contains("://") {
        return path.starts_with("file://");
    }
    let path = path
        .strip_prefix("file:")
        .or_else(|| path.strip_prefix("link:"))
        .unwrap_or(path);
    path == "."
        || path.starts_with("./")
        || path.starts_with("../")
        || path.starts_with('/')
        || path.starts_with("~/")
        || path.contains('/')
        || path.contains('\\')
}

fn pip_local_file_url_path(value: &str) -> Result<Option<PathBuf>, OmcRegistryError> {
    if !value.contains("://") {
        return Ok(None);
    }
    let url = reqwest::Url::parse(value)
        .map_err(|_| OmcRegistryError::UnsupportedSpec(value.to_owned()))?;
    if url.scheme() != "file" {
        return Err(OmcRegistryError::UnsupportedSpec(format!(
            "pip local directory URL `{value}` must use file://"
        )));
    }
    url.to_file_path().map(Some).map_err(|_| {
        OmcRegistryError::UnsupportedSpec(format!(
            "pip local directory URL `{value}` must use a valid file URL"
        ))
    })
}

fn is_pip_pylock_requirements_arg(value: &str) -> bool {
    if value.contains("://") || value.starts_with("git+") {
        return false;
    }
    let path = Path::new(value);
    if !path.is_file() {
        return false;
    }
    let Some(name) = path.file_name().and_then(|name| name.to_str()) else {
        return false;
    };
    name == "pylock.toml" || (name.starts_with("pylock.") && name.ends_with(".toml"))
}

fn pip_local_path_and_extras(value: &str) -> (&str, BTreeSet<String>) {
    let Some((path, extras)) = value.split_once('[') else {
        return (value, BTreeSet::new());
    };
    let extras = extras
        .trim_end_matches(']')
        .split(',')
        .map(normalize_extra)
        .filter(|extra| !extra.is_empty())
        .collect();
    (path, extras)
}

fn is_pip_archive_arg(value: &str) -> bool {
    let value = value.split_once('#').map(|(path, _)| path).unwrap_or(value);
    let filename = value
        .rsplit_once('/')
        .map(|(_, filename)| filename)
        .unwrap_or(value);
    filename.ends_with(".whl")
        || filename.ends_with(".zip")
        || filename.ends_with(".tgz")
        || filename.ends_with(".tar.gz")
}

#[derive(Debug)]
struct CommonCompatFlags {
    dependency_kind: ManifestDependencyKind,
    omit_dev: bool,
    omit_optional: bool,
    omit_peer: bool,
    save: bool,
    save_explicit: bool,
    save_prefix: String,
    save_bundle: bool,
    package_lock: bool,
    lock_only: bool,
    dry_run: bool,
    json: bool,
    npm_registry: Option<String>,
    npm_engine_strict: bool,
    npm_offline: bool,
    allow: Vec<String>,
    allow_flow: Vec<String>,
    allow_all_host: bool,
    workspaces: Vec<String>,
    all_workspaces: bool,
    include_workspace_root: bool,
    positionals: Vec<String>,
}

impl Default for CommonCompatFlags {
    fn default() -> Self {
        Self {
            dependency_kind: ManifestDependencyKind::Production,
            omit_dev: false,
            omit_optional: false,
            omit_peer: false,
            save: true,
            save_explicit: false,
            save_prefix: DEFAULT_NPM_SAVE_PREFIX.to_owned(),
            save_bundle: false,
            package_lock: true,
            lock_only: false,
            dry_run: false,
            json: false,
            npm_registry: None,
            npm_engine_strict: false,
            npm_offline: false,
            allow: Vec::new(),
            allow_flow: Vec::new(),
            allow_all_host: false,
            workspaces: Vec::new(),
            all_workspaces: false,
            include_workspace_root: false,
            positionals: Vec::new(),
        }
    }
}

fn parse_common_compat_flags(
    args: &[String],
    npm_mode: bool,
) -> Result<CommonCompatFlags, OmcRegistryError> {
    let mut parsed = CommonCompatFlags::default();
    let mut index = 0;
    while index < args.len() {
        let arg = &args[index];
        if arg == "--" {
            parsed.positionals.extend(args[index + 1..].iter().cloned());
            break;
        } else if arg == "--allow" {
            index += 1;
            let Some(grant) = args.get(index) else {
                return Err(OmcRegistryError::UnsupportedSpec(
                    "--allow needs a capability grant".to_owned(),
                ));
            };
            parsed.allow.push(grant.clone());
        } else if let Some(grant) = arg.strip_prefix("--allow=") {
            parsed.allow.push(grant.to_owned());
        } else if arg == "--allow-flow" {
            index += 1;
            let Some(flow) = args.get(index) else {
                return Err(OmcRegistryError::UnsupportedSpec(
                    "--allow-flow needs a data-flow grant".to_owned(),
                ));
            };
            parsed.allow_flow.push(flow.clone());
        } else if let Some(flow) = arg.strip_prefix("--allow-flow=") {
            parsed.allow_flow.push(flow.to_owned());
        } else if arg == "--allow-all-host" {
            parsed.allow_all_host = true;
        } else if npm_mode && npm_bool_flag_value(arg, "--dry-run").is_some() {
            parsed.dry_run = npm_bool_flag_value(arg, "--dry-run").unwrap_or(false);
        } else if npm_mode && arg == "--no-dry-run" {
            parsed.dry_run = false;
        } else if npm_mode && npm_json_flag_value(arg).is_some() {
            parsed.json = npm_json_flag_value(arg).unwrap_or(false);
        } else if npm_mode
            && matches!(
                arg.as_str(),
                "--save-bundle"
                    | "--save-bundled"
                    | "-B"
                    | "--save-bundle=true"
                    | "--save-bundled=true"
            )
        {
            parsed.save = true;
            parsed.save_explicit = true;
            parsed.save_bundle = true;
        } else if npm_mode
            && matches!(
                arg.as_str(),
                "--no-save-bundle"
                    | "--no-save-bundled"
                    | "--save-bundle=false"
                    | "--save-bundled=false"
            )
        {
            parsed.save_bundle = false;
        } else if npm_mode && arg == "--no-save" {
            parsed.save = false;
            parsed.save_explicit = true;
        } else if npm_mode && arg == "--save=false" {
            parsed.save = false;
            parsed.save_explicit = true;
        } else if npm_mode {
            if let Some(dependency_kind) = npm_save_location_flag_kind(arg) {
                parsed.dependency_kind = dependency_kind;
                parsed.save = true;
                parsed.save_explicit = true;
                index += 1;
                continue;
            }
            if matches!(arg.as_str(), "--save-exact" | "-E" | "--save-exact=true") {
                parsed.save_prefix.clear();
                index += 1;
                continue;
            }
            if arg == "--save-exact=false" {
                parsed.save_prefix = DEFAULT_NPM_SAVE_PREFIX.to_owned();
                index += 1;
                continue;
            }
            if arg == "--save-prefix" {
                index += 1;
                let Some(prefix) = args.get(index) else {
                    return Err(OmcRegistryError::UnsupportedSpec(
                        "--save-prefix needs a value".to_owned(),
                    ));
                };
                parsed.save_prefix = prefix.clone();
                index += 1;
                continue;
            }
            if let Some(prefix) = arg.strip_prefix("--save-prefix=") {
                parsed.save_prefix = prefix.to_owned();
                index += 1;
                continue;
            }
            if arg == "--registry" {
                index += 1;
                let Some(registry) = args.get(index) else {
                    return Err(OmcRegistryError::UnsupportedSpec(
                        "--registry needs a URL".to_owned(),
                    ));
                };
                parsed.npm_registry = Some(registry.clone());
                index += 1;
                continue;
            }
            if let Some(lock_only) = npm_bool_flag_value(arg, "--package-lock-only") {
                parsed.lock_only = lock_only;
                index += 1;
                continue;
            }
            if let Some(package_lock) = npm_bool_flag_value(arg, "--package-lock") {
                parsed.package_lock = package_lock;
                index += 1;
                continue;
            }
            if arg == "--no-package-lock" {
                parsed.package_lock = false;
                index += 1;
                continue;
            }
            if let Some(engine_strict) = npm_bool_flag_value(arg, "--engine-strict") {
                parsed.npm_engine_strict = engine_strict;
                index += 1;
                continue;
            }
            if arg == "--no-engine-strict" {
                parsed.npm_engine_strict = false;
                index += 1;
                continue;
            }
            if let Some(offline) = npm_bool_flag_value(arg, "--offline") {
                parsed.npm_offline = offline;
                index += 1;
                continue;
            }
            if arg == "--no-offline" {
                parsed.npm_offline = false;
                index += 1;
                continue;
            }
            if let Some(registry) = arg.strip_prefix("--registry=") {
                parsed.npm_registry = Some(registry.to_owned());
                index += 1;
                continue;
            }
            if matches!(
                arg.as_str(),
                "--omit-dev" | "--production" | "--prod" | "--only=production"
            ) {
                parsed.omit_dev = true;
            } else if arg == "--only=prod" {
                parsed.omit_dev = true;
            } else if matches!(arg.as_str(), "--only=development" | "--only=dev") {
                parsed.omit_dev = false;
            } else if arg == "--only" {
                index += 1;
                let Some(value) = args.get(index) else {
                    return Err(OmcRegistryError::UnsupportedSpec(
                        "--only needs a value".to_owned(),
                    ));
                };
                apply_npm_only_value(&mut parsed, value);
            } else if arg == "--also" {
                index += 1;
                let Some(value) = args.get(index) else {
                    return Err(OmcRegistryError::UnsupportedSpec(
                        "--also needs a value".to_owned(),
                    ));
                };
                apply_npm_also_value(&mut parsed, value);
            } else if let Some(value) = arg.strip_prefix("--also=") {
                apply_npm_also_value(&mut parsed, value);
            } else if matches!(arg.as_str(), "--production=false" | "--prod=false") {
                parsed.omit_dev = false;
            } else if matches!(arg.as_str(), "--no-optional" | "--optional=false") {
                parsed.omit_optional = true;
            } else if matches!(arg.as_str(), "--optional" | "--optional=true") {
                parsed.omit_optional = false;
            } else if let Some(value) = arg.strip_prefix("--omit=") {
                parsed.omit_dev |= npm_dependency_set_contains(value, "dev");
                parsed.omit_optional |= npm_dependency_set_contains(value, "optional");
                parsed.omit_peer |= npm_dependency_set_contains(value, "peer");
            } else if let Some(value) = arg.strip_prefix("--include=") {
                if npm_dependency_set_contains(value, "dev") {
                    parsed.omit_dev = false;
                }
                if npm_dependency_set_contains(value, "optional") {
                    parsed.omit_optional = false;
                }
                if npm_dependency_set_contains(value, "peer") {
                    parsed.omit_peer = false;
                }
            } else if arg == "--omit" {
                index += 1;
                let Some(value) = args.get(index) else {
                    return Err(OmcRegistryError::UnsupportedSpec(
                        "--omit needs a value".to_owned(),
                    ));
                };
                parsed.omit_dev |= npm_dependency_set_contains(value, "dev");
                parsed.omit_optional |= npm_dependency_set_contains(value, "optional");
                parsed.omit_peer |= npm_dependency_set_contains(value, "peer");
            } else if arg == "--include" {
                index += 1;
                let Some(value) = args.get(index) else {
                    return Err(OmcRegistryError::UnsupportedSpec(
                        "--include needs a value".to_owned(),
                    ));
                };
                if npm_dependency_set_contains(value, "dev") {
                    parsed.omit_dev = false;
                }
                if npm_dependency_set_contains(value, "optional") {
                    parsed.omit_optional = false;
                }
                if npm_dependency_set_contains(value, "peer") {
                    parsed.omit_peer = false;
                }
            } else if matches!(arg.as_str(), "--workspace" | "-w") {
                index += 1;
                let Some(workspace) = args.get(index) else {
                    return Err(OmcRegistryError::UnsupportedSpec(format!(
                        "{arg} needs a workspace"
                    )));
                };
                parsed.workspaces.push(workspace.clone());
            } else if let Some(workspace) = arg
                .strip_prefix("--workspace=")
                .or_else(|| arg.strip_prefix("-w="))
            {
                parsed.workspaces.push(workspace.to_owned());
            } else if let Some(value) = npm_all_workspaces_flag_value(arg) {
                parsed.all_workspaces = value;
            } else if let Some(workspace) = npm_attached_short_value(arg, 'w') {
                parsed.workspaces.push(workspace.to_owned());
            } else if let Some(value) = npm_include_workspace_root_flag_value(arg) {
                parsed.include_workspace_root = value;
            } else if ignored_npm_value_flag(arg) {
                index += 1;
                if args.get(index).is_none() {
                    return Err(OmcRegistryError::UnsupportedSpec(format!(
                        "{arg} needs a value"
                    )));
                }
            } else if ignored_compat_flag(npm_mode, arg) {
            } else if arg.starts_with('-') {
                return Err(unsupported_compat_arg("compatibility command", arg));
            } else {
                parsed.positionals.push(arg.clone());
            }
        } else if ignored_compat_flag(npm_mode, arg) {
        } else if arg.starts_with('-') {
            return Err(unsupported_compat_arg("compatibility command", arg));
        } else {
            parsed.positionals.push(arg.clone());
        }
        index += 1;
    }
    Ok(parsed)
}

fn apply_npm_only_value(parsed: &mut CommonCompatFlags, value: &str) {
    if npm_dependency_set_contains(value, "production")
        || npm_dependency_set_contains(value, "prod")
    {
        parsed.omit_dev = true;
    } else if npm_dependency_set_contains(value, "development")
        || npm_dependency_set_contains(value, "dev")
    {
        parsed.omit_dev = false;
    }
}

fn apply_npm_also_value(parsed: &mut CommonCompatFlags, value: &str) {
    if npm_dependency_set_contains(value, "development")
        || npm_dependency_set_contains(value, "dev")
    {
        parsed.omit_dev = false;
    }
    if npm_dependency_set_contains(value, "optional") {
        parsed.omit_optional = false;
    }
    if npm_dependency_set_contains(value, "peer") {
        parsed.omit_peer = false;
    }
}

fn npm_save_location_flag_kind(arg: &str) -> Option<ManifestDependencyKind> {
    match arg {
        "--save"
        | "-S"
        | "--save=true"
        | "--save-prod"
        | "-P"
        | "--save-prod=true"
        | "--save-prod=false"
        | "--no-save-prod"
        | "--save-dev=false"
        | "--dev=false"
        | "--no-save-dev"
        | "--no-dev"
        | "--save-optional=false"
        | "--no-save-optional"
        | "--save-peer=false"
        | "--no-save-peer" => Some(ManifestDependencyKind::Production),
        "-D" | "--save-dev" | "--dev" | "--save-dev=true" | "--dev=true" => {
            Some(ManifestDependencyKind::Dev)
        }
        "--save-optional" | "-O" | "--save-optional=true" => Some(ManifestDependencyKind::Optional),
        "--save-peer" | "--save-peer=true" => Some(ManifestDependencyKind::Peer),
        _ => None,
    }
}

fn npm_dependency_set_contains(value: &str, target: &str) -> bool {
    value
        .split(',')
        .map(str::trim)
        .any(|part| part.eq_ignore_ascii_case(target))
}

fn ignored_compat_flag(npm_mode: bool, arg: &str) -> bool {
    if npm_mode {
        matches!(
            arg,
            "--silent"
                | "-s"
                | "--quiet"
                | "-q"
                | "--no-progress"
                | "--progress=false"
                | "--no-color"
                | "--color=false"
                | "--save-exact"
                | "--engine-strict=false"
        ) || ignored_npm_install_preference_flag(arg)
            || ignored_npm_equals_flag(arg)
    } else {
        arg == "-y"
    }
}

fn ignored_npm_install_preference_flag(arg: &str) -> bool {
    matches!(
        arg,
        "--ignore-scripts"
            | "--ignore-scripts=true"
            | "--ignore-scripts=false"
            | "--no-ignore-scripts"
            | "--foreground-scripts"
            | "--foreground-scripts=true"
            | "--foreground-scripts=false"
            | "--no-foreground-scripts"
            | "--fund"
            | "--fund=true"
            | "--fund=false"
            | "--no-fund"
            | "--audit"
            | "--audit=true"
            | "--audit=false"
            | "--no-audit"
            | "--legacy-peer-deps"
            | "--legacy-peer-deps=true"
            | "--legacy-peer-deps=false"
            | "--no-legacy-peer-deps"
            | "--strict-peer-deps"
            | "--strict-peer-deps=true"
            | "--strict-peer-deps=false"
            | "--no-strict-peer-deps"
            | "--prefer-offline"
            | "--prefer-offline=true"
            | "--prefer-offline=false"
            | "--no-prefer-offline"
            | "--prefer-online"
            | "--prefer-online=true"
            | "--prefer-online=false"
            | "--no-prefer-online"
            | "--prefer-dedupe"
            | "--prefer-dedupe=true"
            | "--prefer-dedupe=false"
            | "--no-prefer-dedupe"
            | "--install-links"
            | "--install-links=true"
            | "--install-links=false"
            | "--no-install-links"
            | "--bin-links"
            | "--bin-links=true"
            | "--bin-links=false"
            | "--no-bin-links"
            | "--global-style"
            | "--global-style=true"
            | "--global-style=false"
            | "--no-global-style"
            | "--legacy-bundling"
            | "--legacy-bundling=true"
            | "--legacy-bundling=false"
            | "--no-legacy-bundling"
    )
}

fn ignored_npm_value_flag(arg: &str) -> bool {
    matches!(
        arg,
        "--install-strategy" | "--cache" | "--registry" | "--loglevel" | "--progress" | "--color"
    )
}

fn ignored_npm_equals_flag(arg: &str) -> bool {
    [
        "--install-strategy=",
        "--cache=",
        "--loglevel=",
        "--progress=",
        "--color=",
        "--install-links=",
    ]
    .iter()
    .any(|prefix| arg.starts_with(prefix))
        || ignored_npm_install_preference_equals_flag(arg)
}

fn ignored_npm_install_preference_equals_flag(arg: &str) -> bool {
    [
        "--ignore-scripts=",
        "--foreground-scripts=",
        "--fund=",
        "--audit=",
        "--legacy-peer-deps=",
        "--strict-peer-deps=",
        "--prefer-offline=",
        "--prefer-online=",
        "--prefer-dedupe=",
        "--install-links=",
        "--bin-links=",
        "--global-style=",
        "--legacy-bundling=",
    ]
    .iter()
    .any(|prefix| arg.starts_with(prefix))
}

fn parse_npm_list_args(args: &[String]) -> Result<NpmCompatAction, OmcRegistryError> {
    let mut json = false;
    let mut depth = 0usize;
    let mut packages = Vec::new();
    let mut index = 0;
    while index < args.len() {
        let arg = &args[index];
        if let Some(value) = npm_json_flag_value(arg) {
            json = value;
        } else if let Some(value) = npm_list_all_flag_value(arg) {
            if value {
                depth = usize::MAX;
            } else {
                depth = 0;
            }
        } else if let Some(value) = npm_list_short_all_flag_value(arg) {
            if value {
                depth = usize::MAX;
            }
        } else if arg == "--depth" {
            index += 1;
            let Some(value) = args.get(index) else {
                return Err(OmcRegistryError::UnsupportedSpec(
                    "--depth needs a value".to_owned(),
                ));
            };
            depth = parse_npm_list_depth(value)?;
        } else if let Some(value) = arg.strip_prefix("--depth=") {
            depth = parse_npm_list_depth(value)?;
        } else if matches!(
            arg.as_str(),
            "--long"
                | "--parseable"
                | "-p"
                | "--production"
                | "--prod"
                | "--dev"
                | "--global"
                | "-g"
                | "--silent"
                | "-s"
                | "--color=false"
                | "--no-color"
        ) || npm_workspace_scope_ignored_flag(arg)
        {
        } else if matches!(
            arg.as_str(),
            "--omit" | "--include" | "--loglevel" | "--workspace" | "-w"
        ) {
            index += 1;
            if args.get(index).is_none() {
                return Err(OmcRegistryError::UnsupportedSpec(format!(
                    "{arg} needs a value"
                )));
            }
        } else if npm_list_ignored_equals_flag(arg) {
        } else if arg.starts_with('-') {
            return Err(unsupported_compat_arg("npm list", arg));
        } else {
            packages.push(arg.clone());
        }
        index += 1;
    }
    Ok(NpmCompatAction::List {
        action: NpmListAction {
            json,
            depth,
            packages,
        },
    })
}

fn npm_list_all_flag_value(arg: &str) -> Option<bool> {
    match arg {
        "--all" | "--all=true" => Some(true),
        "--all=false" | "--no-all" => Some(false),
        _ => None,
    }
}

fn npm_list_short_all_flag_value(arg: &str) -> Option<bool> {
    let rest = arg.strip_prefix('-')?;
    if rest.is_empty() || rest.starts_with('-') {
        return None;
    }
    rest.chars()
        .all(|ch| matches!(ch, 'a' | 'l'))
        .then(|| rest.contains('a'))
}

fn parse_npm_list_depth(value: &str) -> Result<usize, OmcRegistryError> {
    if value.eq_ignore_ascii_case("infinity") {
        return Ok(usize::MAX);
    }
    value.parse::<usize>().map_err(|_| {
        OmcRegistryError::UnsupportedSpec(format!("unsupported npm list depth `{value}`"))
    })
}

fn parse_npm_query_args(args: &[String]) -> Result<NpmCompatAction, OmcRegistryError> {
    let mut selector = None;
    let mut workspaces = Vec::new();
    let mut all_workspaces = false;
    let mut include_workspace_root = false;
    let mut package_lock_only = false;
    let mut expect_results = None;
    let mut expect_result_count = None;
    let mut index = 0;
    while index < args.len() {
        let arg = &args[index];
        if matches!(
            arg.as_str(),
            "--json" | "--json=true" | "--json=false" | "--silent" | "-s" | "--parseable" | "-p"
        ) {
        } else if matches!(
            arg.as_str(),
            "--package-lock-only" | "--package-lock-only=true"
        ) {
            package_lock_only = true;
        } else if arg == "--package-lock-only=false" {
            package_lock_only = false;
        } else if let Some(value) = npm_all_workspaces_flag_value(arg) {
            all_workspaces = value;
        } else if let Some(value) = npm_include_workspace_root_flag_value(arg) {
            include_workspace_root = value;
        } else if matches!(arg.as_str(), "--expect-results" | "--expect-results=true") {
            expect_results = Some(true);
        } else if matches!(
            arg.as_str(),
            "--no-expect-results" | "--expect-results=false"
        ) {
            expect_results = Some(false);
        } else if arg == "--expect-result-count" {
            index += 1;
            expect_result_count = Some(parse_npm_query_expected_count(&npm_query_flag_value(
                args, index, arg,
            )?)?);
        } else if let Some(value) = arg.strip_prefix("--expect-result-count=") {
            expect_result_count = Some(parse_npm_query_expected_count(value)?);
        } else if matches!(arg.as_str(), "--workspace" | "-w") {
            index += 1;
            workspaces.push(npm_query_flag_value(args, index, arg)?);
        } else if let Some(value) = arg
            .strip_prefix("--workspace=")
            .or_else(|| arg.strip_prefix("-w="))
        {
            workspaces.push(value.to_owned());
        } else if matches!(arg.as_str(), "--loglevel" | "--cache") {
            index += 1;
            if args.get(index).is_none() {
                return Err(OmcRegistryError::UnsupportedSpec(format!(
                    "{arg} needs a value"
                )));
            }
        } else if npm_query_ignored_equals_flag(arg) {
        } else if arg.starts_with('-') {
            return Err(unsupported_compat_arg("npm query", arg));
        } else if selector.is_none() {
            selector = Some(arg.clone());
        } else {
            return Err(unsupported_compat_arg("npm query", arg));
        }
        index += 1;
    }
    let selector = selector.ok_or_else(|| {
        OmcRegistryError::UnsupportedSpec("npm query needs a selector".to_owned())
    })?;
    Ok(NpmCompatAction::Query {
        action: NpmQueryAction {
            selector,
            workspaces,
            all_workspaces,
            include_workspace_root,
            package_lock_only,
            expect_results,
            expect_result_count,
        },
    })
}

fn parse_npm_query_expected_count(value: &str) -> Result<usize, OmcRegistryError> {
    value.parse::<usize>().map_err(|_| {
        OmcRegistryError::UnsupportedSpec(format!("invalid npm query expected count `{value}`"))
    })
}

fn npm_query_flag_value(
    args: &[String],
    index: usize,
    flag: &str,
) -> Result<String, OmcRegistryError> {
    args.get(index)
        .cloned()
        .ok_or_else(|| OmcRegistryError::UnsupportedSpec(format!("{flag} needs a value")))
}

fn npm_query_ignored_equals_flag(arg: &str) -> bool {
    ["--loglevel=", "--cache=", "--parseable="]
        .iter()
        .any(|prefix| arg.starts_with(prefix))
}

fn npm_list_ignored_equals_flag(arg: &str) -> bool {
    [
        "--depth=",
        "--omit=",
        "--include=",
        "--loglevel=",
        "--workspace=",
        "--userconfig=",
        "--parseable=",
    ]
    .iter()
    .any(|prefix| arg.starts_with(prefix))
}

fn parse_pip_list_args(args: &[String]) -> Result<PipCompatAction, OmcRegistryError> {
    let expanded_short_clusters = expand_pip_list_short_clusters(args);
    let args = expanded_short_clusters.as_slice();
    let mut format = PipListFormat::Columns;
    let mut verbose = false;
    let mut outdated = false;
    let mut uptodate = false;
    let mut index_url = None;
    let mut extra_index_urls = Vec::new();
    let mut find_links = Vec::new();
    let mut no_index = false;
    let mut allow_prereleases = false;
    let mut paths = Vec::new();
    let mut user = false;
    let mut exclude = Vec::new();
    let mut editable = PipEditableMode::Include;
    let mut not_required = false;
    let mut index = 0;
    while index < args.len() {
        let arg = &args[index];
        if arg == "--format" {
            index += 1;
            let Some(value) = args.get(index) else {
                return Err(OmcRegistryError::UnsupportedSpec(
                    "pip list --format needs a value".to_owned(),
                ));
            };
            format = parse_pip_list_format_value(value)?;
        } else if let Some(value) = arg.strip_prefix("--format=") {
            format = parse_pip_list_format_value(value)?;
        } else if arg == "-o" || arg == "--outdated" {
            outdated = true;
        } else if arg == "-u" || arg == "--uptodate" {
            uptodate = true;
        } else if arg == "-i" || arg == "--index-url" {
            index += 1;
            let Some(url) = args.get(index) else {
                return Err(OmcRegistryError::UnsupportedSpec(format!(
                    "{arg} needs a URL"
                )));
            };
            index_url = Some(url.clone());
        } else if let Some(url) = arg.strip_prefix("--index-url=") {
            index_url = Some(url.to_owned());
        } else if let Some(url) = pip_attached_short_value(arg, 'i') {
            index_url = Some(url.to_owned());
        } else if arg == "--extra-index-url" {
            index += 1;
            let Some(url) = args.get(index) else {
                return Err(OmcRegistryError::UnsupportedSpec(format!(
                    "{arg} needs a URL"
                )));
            };
            extra_index_urls.push(url.clone());
        } else if let Some(url) = arg.strip_prefix("--extra-index-url=") {
            extra_index_urls.push(url.to_owned());
        } else if arg == "-f" || arg == "--find-links" {
            index += 1;
            let Some(value) = args.get(index) else {
                return Err(OmcRegistryError::UnsupportedSpec(format!(
                    "{arg} needs a path or URL"
                )));
            };
            find_links.push(value.clone());
        } else if let Some(value) = arg.strip_prefix("--find-links=") {
            find_links.push(value.to_owned());
        } else if let Some(value) = pip_attached_short_value(arg, 'f') {
            find_links.push(value.to_owned());
        } else if arg == "--no-index" {
            no_index = true;
        } else if arg == "--pre" {
            allow_prereleases = true;
        } else if arg == "--user" {
            user = true;
        } else if pip_verbose_flag(arg) {
            verbose = true;
        } else if matches!(
            arg.as_str(),
            "--local" | "-l" | "--disable-pip-version-check" | "--ignore-requires-python"
        ) || pip_ignored_verbosity_flag(arg)
        {
        } else if arg == "-e" || arg == "--editable" {
            editable = PipEditableMode::Only;
        } else if arg == "--include-editable" {
            editable = PipEditableMode::Include;
        } else if arg == "--exclude-editable" {
            editable = PipEditableMode::Exclude;
        } else if arg == "--not-required" {
            not_required = true;
        } else if matches!(arg.as_str(), "--path" | "--exclude") {
            index += 1;
            let Some(value) = args.get(index) else {
                return Err(OmcRegistryError::UnsupportedSpec(format!(
                    "{arg} needs a value"
                )));
            };
            if arg == "--path" {
                paths.push(PathBuf::from(value));
            } else {
                exclude.push(value.clone());
            }
        } else if let Some(path) = arg.strip_prefix("--path=") {
            paths.push(PathBuf::from(path));
        } else if let Some(name) = arg.strip_prefix("--exclude=") {
            exclude.push(name.to_owned());
        } else if pip_index_ignored_value_flag(arg) {
            index += 1;
            if args.get(index).is_none() {
                return Err(OmcRegistryError::UnsupportedSpec(format!(
                    "{arg} needs a value"
                )));
            }
        } else if pip_index_ignored_equals_flag(arg) {
        } else {
            return Err(unsupported_compat_arg("pip list", arg));
        }
        index += 1;
    }
    if outdated && uptodate {
        return Err(OmcRegistryError::UnsupportedSpec(
            "pip list cannot combine --outdated and --uptodate".to_owned(),
        ));
    }
    Ok(PipCompatAction::List {
        format,
        verbose,
        outdated,
        uptodate,
        paths,
        user,
        exclude,
        editable,
        not_required,
        index_url,
        extra_index_urls,
        find_links,
        no_index,
        allow_prereleases,
    })
}

fn expand_pip_list_short_clusters(args: &[String]) -> Vec<String> {
    args.iter()
        .flat_map(|arg| {
            expand_pip_short_cluster(arg, &['o', 'u', 'e', 'l'], &['i', 'f'])
                .unwrap_or_else(|| vec![arg.clone()])
        })
        .collect()
}

fn parse_pip_list_format_value(value: &str) -> Result<PipListFormat, OmcRegistryError> {
    match value {
        "columns" => Ok(PipListFormat::Columns),
        "freeze" => Ok(PipListFormat::Freeze),
        "json" => Ok(PipListFormat::Json),
        other => Err(OmcRegistryError::UnsupportedSpec(format!(
            "unsupported pip list format `{other}`"
        ))),
    }
}

fn pip_uninstall_specs_from_requirements(
    project_dir: &Path,
    requirements: Vec<PathBuf>,
) -> Result<Vec<String>, OmcRegistryError> {
    if requirements.is_empty() {
        return Ok(Vec::new());
    }

    let requirements = read_requirements_files(&absolutize_paths(project_dir, requirements))?;

    let mut specs = requirements
        .specs
        .into_iter()
        .map(|spec| spec.package_key())
        .collect::<Vec<_>>();
    specs.extend(
        requirements
            .python_vcs_requirements
            .into_iter()
            .map(|requirement| format!("pypi:{}", requirement.name)),
    );
    specs.extend(pip_uninstall_local_path_specs(
        requirements.python_local_paths,
        requirements.python_local_requirements,
    )?);
    Ok(specs)
}

fn pip_uninstall_local_path_specs(
    local_paths: Vec<PathBuf>,
    local_requirements: Vec<PythonLocalRequirement>,
) -> Result<Vec<String>, OmcRegistryError> {
    let mut specs = Vec::new();
    let mut seen = BTreeSet::new();
    for path in local_paths.into_iter().chain(
        local_requirements
            .into_iter()
            .map(|requirement| requirement.path),
    ) {
        let Some(package) = pip_local_editable_package(&path)? else {
            return Err(OmcRegistryError::UnsupportedSpec(format!(
                "pip uninstall -r cannot remove unnamed local path requirement `{}`",
                path.display()
            )));
        };
        if seen.insert(normalize_pip_show_name(&package.name)) {
            specs.push(format!("pypi:{}", package.name));
        }
    }
    Ok(specs)
}

fn split_first_position(
    command: &str,
    args: &[String],
) -> Result<(String, Vec<String>), OmcRegistryError> {
    let mut args = args.to_vec();
    if args.first().map(String::as_str) == Some("--") {
        args.remove(0);
    }
    if args.is_empty() {
        return Err(OmcRegistryError::UnsupportedSpec(format!(
            "{command} needs a target"
        )));
    }
    let name = args.remove(0);
    if args.first().map(String::as_str) == Some("--") {
        args.remove(0);
    }
    Ok((name, args))
}

fn unsupported_compat_arg(command: &str, arg: &str) -> OmcRegistryError {
    OmcRegistryError::UnsupportedSpec(format!(
        "{command} does not support compatibility argument `{arg}`"
    ))
}

fn parse_grants(
    allow: &[String],
    allow_all_host: bool,
) -> Result<Vec<Capability>, OmcRegistryError> {
    let mut grants = allow
        .iter()
        .map(|grant| parse_capability_grant(grant))
        .collect::<Result<Vec<_>, _>>()?;

    if allow_all_host {
        grants.extend([
            Capability::EnvRead("*".to_owned()),
            Capability::FsRead("*".to_owned()),
            Capability::FsWrite("*".to_owned()),
            Capability::HttpHost("*".to_owned()),
            Capability::DnsHost("*".to_owned()),
            Capability::ProcSpawn("*".to_owned()),
            Capability::DynamicEval,
            Capability::TimeNow,
            Capability::RandomBytes,
        ]);
    }

    Ok(grants)
}

fn parse_flow_grants(allow_flow: &[String]) -> Result<Vec<omc_cap::FlowRule>, OmcRegistryError> {
    allow_flow
        .iter()
        .map(|flow| parse_flow_rule(flow))
        .collect()
}

fn apply_cli_policy_options(
    options: &mut LinkOptions,
    allow: &[String],
    allow_flow: &[String],
    allow_all_host: bool,
) -> Result<(), OmcRegistryError> {
    options.allowed_capabilities = parse_grants(allow, allow_all_host)?;
    options.allowed_flows = parse_flow_grants(allow_flow)?;
    Ok(())
}

fn parse_package_specs(
    specs: &[String],
    ecosystem_hint: Option<Ecosystem>,
) -> Result<Vec<PackageSpec>, OmcRegistryError> {
    specs
        .iter()
        .map(|spec| parse_package_spec(spec, ecosystem_hint))
        .collect::<Result<Vec<_>, _>>()
}

fn parse_package_spec(
    spec: &str,
    ecosystem_hint: Option<Ecosystem>,
) -> Result<PackageSpec, OmcRegistryError> {
    if package_spec_has_ecosystem_prefix(spec) {
        return PackageSpec::parse(spec);
    }

    let Some(ecosystem) = ecosystem_hint else {
        return PackageSpec::parse(spec);
    };

    PackageSpec::parse(&format!("{ecosystem}:{spec}"))
}

fn package_spec_has_ecosystem_prefix(spec: &str) -> bool {
    spec.split_once(':')
        .map(|(prefix, _)| matches!(prefix, "npm" | "pypi" | "py" | "python"))
        .unwrap_or(false)
}

fn ecosystem_hint(npm: bool, pypi: bool) -> Option<Ecosystem> {
    if npm {
        Some(Ecosystem::Npm)
    } else if pypi {
        Some(Ecosystem::Pypi)
    } else {
        None
    }
}

fn dependency_kind_from_booleans(dev: bool, optional: bool, peer: bool) -> ManifestDependencyKind {
    if dev {
        ManifestDependencyKind::Dev
    } else if optional {
        ManifestDependencyKind::Optional
    } else if peer {
        ManifestDependencyKind::Peer
    } else {
        ManifestDependencyKind::Production
    }
}

fn normalize_extra(extra: &str) -> String {
    extra.trim().replace('_', "-").to_ascii_lowercase()
}

