    fn test_dir(name: &str) -> PathBuf {
        let nonce = std::time::SystemTime::now()
            .duration_since(std::time::UNIX_EPOCH)
            .unwrap()
            .as_nanos();
        let dir = env::temp_dir().join(format!("omc-cli-{name}-{nonce}"));
        let _ = fs::remove_dir_all(&dir);
        fs::create_dir_all(&dir).unwrap();
        dir
    }

    fn pypi_sdist_for_test(root: &str, files: &[(&str, &str)]) -> Vec<u8> {
        let encoder = GzEncoder::new(Vec::new(), Compression::default());
        let mut archive = tar::Builder::new(encoder);
        for (path, content) in files {
            let archive_path = format!("{root}/{path}");
            let mut header = tar::Header::new_gnu();
            header.set_size(content.len() as u64);
            header.set_mode(0o644);
            header.set_cksum();
            archive
                .append_data(
                    &mut header,
                    archive_path,
                    &mut std::io::Cursor::new(content.as_bytes()),
                )
                .unwrap();
        }
        let encoder = archive.into_inner().unwrap();
        encoder.finish().unwrap()
    }

    fn with_env_lock<T>(f: impl FnOnce() -> T) -> T {
        static ENV_MUTEX: std::sync::OnceLock<std::sync::Mutex<()>> = std::sync::OnceLock::new();
        let _guard = ENV_MUTEX
            .get_or_init(|| std::sync::Mutex::new(()))
            .lock()
            .unwrap();
        f()
    }

    fn with_env_var<T>(key: &str, value: &Path, f: impl FnOnce() -> T) -> T {
        with_env_lock(|| {
            let old = env::var_os(key);
            env::set_var(key, value);
            let result = f();
            if let Some(old) = old {
                env::set_var(key, old);
            } else {
                env::remove_var(key);
            }
            result
        })
    }

    fn without_env_var<T>(key: &str, f: impl FnOnce() -> T) -> T {
        with_env_lock(|| {
            let old = env::var_os(key);
            env::remove_var(key);
            let result = f();
            if let Some(old) = old {
                env::set_var(key, old);
            }
            result
        })
    }

    fn with_env_values<T>(values: &[(&str, Option<&str>)], f: impl FnOnce() -> T) -> T {
        with_env_lock(|| {
            let old_values = values
                .iter()
                .map(|(key, _)| (*key, env::var_os(key)))
                .collect::<Vec<_>>();
            for (key, value) in values {
                if let Some(value) = value {
                    env::set_var(key, value);
                } else {
                    env::remove_var(key);
                }
            }
            let result = f();
            for (key, old) in old_values {
                if let Some(old) = old {
                    env::set_var(key, old);
                } else {
                    env::remove_var(key);
                }
            }
            result
        })
    }

